import { applyCaseLaw, type CaseLaw } from "@/lib/case-law";

export type { CaseLaw };

export type Citation = { label: string; href: string };

export type SentenceRead = {
  id: string;
  text: string;
  seconds: number;
  truth: number;
  reasons: string[];
  citation: Citation | null;
  caseLaw: CaseLaw[];
  clock?: string;
  deskNote?: string;
  oldStudio?: string;
};

export type StudioRead = {
  id: string;
  title: string;
  speaker: string;
  kind: "sample" | "paste" | "url";
  sourceUrl?: string;
  sentences: SentenceRead[];
  rollup: number;
  formula: string;
};

export type OutletDiff = {
  both: string[];
  onlyA: string[];
  onlyB: string[];
};

const CITATIONS: { test: RegExp; label: string; href: string }[] = [
  {
    test: /arizona v\. united states|567 u\.s\. 387|11-182/i,
    label: "Arizona v. United States, 567 U.S. 387 (2012) — opinion PDF",
    href: "https://www.supremecourt.gov/opinions/11pdf/11-182.pdf",
  },
  {
    test: /§\s*1357|section 1357|u\.?\s*s\.?\s*code §\s*1357/i,
    label: "8 U.S.C. § 1357 — Office of the Law Revision Counsel",
    href: "https://uscode.house.gov/view.xhtml?req=granuleid:USC-prelim-title8-section1357&num=0&edition=prelim",
  },
  {
    test: /§\s*1324|section 1324|harboring/i,
    label: "8 U.S.C. § 1324 — Office of the Law Revision Counsel",
    href: "https://uscode.house.gov/view.xhtml?req=granuleid:USC-prelim-title8-section1324&num=0&edition=prelim",
  },
  {
    test: /article vi/i,
    label: "Constitution of the United States, Article VI",
    href: "https://constitution.congress.gov/constitution/article-6/",
  },
  {
    test: /appropriations/i,
    label: "Congress.gov — DHS appropriations search",

    href: "https://www.congress.gov/quick-search/legislation?wordsPhrases=Department+of+Homeland+Security+appropriations",
  },
  {
    test: /census bureau|employment release/i,
    label: "U.S. Census Bureau",
    href: "https://www.census.gov/",
  },
  {
    test: /congress\.gov|bill text/i,
    label: "Congress.gov",
    href: "https://www.congress.gov/",
  },
  {
    test: /eoir|immigration judge/i,
    label: "Executive Office for Immigration Review",
    href: "https://www.justice.gov/eoir",
  },
  {
    test: /purcell v|549 u\.s\. 1/i,
    label: "Purcell v. Gonzalez, 549 U.S. 1 (2006)",
    href: "https://supreme.justia.com/cases/federal/us/549/1/",
  },
  {
    test: /§\s*1862|section 232|19 u\.?\s*s\.?\s*c\.?\s*§\s*1862/i,
    label: "19 U.S.C. § 1862 — Section 232",
    href: "https://uscode.house.gov/view.xhtml?req=granuleid:USC-prelim-title19-section1862&num=0&edition=prelim",
  },
  {
    test: /19 cfr|§\s*141\.1|importer of record/i,
    label: "19 CFR § 141.1 — importer liability for duties",
    href: "https://www.ecfr.gov/current/title-19/chapter-I/part-141/section-141.1",
  },
  {
    test: /bureau of labor|current employment statistics/i,
    label: "Bureau of Labor Statistics — employment",
    href: "https://www.bls.gov/ces/",
  },
];

const ABSOLUTE =
  /\b(completely|absolute(?:ly)?|absolute zero|five hundred percent|500%|without any|charged personally|will be charged|guaranteed|everyone|never|always|banned every|no effect|every single|one hundred percent|exactly zero|entire country|zero federal|permanently)\b/gi;

const HEDGE = /\b(may|might|could|approximately|about|roughly|suggests)\b/gi;

function clamp(n: number) {
  return Math.max(8, Math.min(96, Math.round(n)));
}

function findCitation(text: string): Citation | null {

  for (const row of CITATIONS) {
    if (row.test.test(text)) return { label: row.label, href: row.href };
  }
  return null;
}

export type ScorePart = { label: string; points: number };

export function scoreSentence(text: string, seconds = 20): Omit<SentenceRead, "id" | "deskNote"> & { parts: ScorePart[] } {
  const citation = findCitation(text);
  const caseLaw = applyCaseLaw(text);
  const absolutes = text.match(ABSOLUTE)?.length ?? 0;
  const hedges = text.match(HEDGE)?.length ?? 0;
  const hasNumber = /\d/.test(text);
  let truth = 55;
  const parts: ScorePart[] = [{ label: "Starts at 55", points: 55 }];
  const reasons: string[] = ["Starts at 55. This score only looks at the words."];
  if (citation) {
    truth += 22;
    parts.push({ label: "Names a known source", points: 22 });
    reasons.push("+22 The sentence names a source this desk knows.");
  } else {
    reasons.push("The sentence does not name a source.");
  }
  if (absolutes) {
    const hit = Math.min(36, absolutes * 18);
    truth -= hit;
    parts.push({ label: "Sweeping words", points: -hit });
    reasons.push(`−${hit} for sweeping words such as “every,” “never,” or “five hundred percent.”`);
  }
  if (hedges) {
    const hit = Math.min(8, hedges * 4);
    truth -= hit;
    parts.push({ label: "Soft words", points: -hit });
    reasons.push(`−${hit} for soft words such as “may” or “could.” Doubt is not a lie.`);
  }
  if (hasNumber && !citation) {
    truth -= 8;
    parts.push({ label: "Number with no source", points: -8 });
    reasons.push("−8 A number appears with no source beside it.");
  }
  truth = clamp(truth);
  reasons.push(
    caseLaw.length
      ? "The case notes do not change this number."
      : "No case in this desk matched. The number is still not a court ruling.",
  );

  return { text: text.trim(), seconds, truth, reasons, citation, caseLaw, parts };
}

export function splitSentences(raw: string): string[] {
  return raw
    .replace(/\s+/g, " ")
    .split(/(?<=[.!?])\s+/)
    .map((s) => s.trim())
    .filter((s) => s.length >= 40)
    .slice(0, 12);
}

export function rollup(sentences: { truth: number; seconds: number }[]) {
  const weight = sentences.reduce((sum, s) => sum + s.seconds, 0);
  if (!weight) return { rollup: 0, formula: "No sentences." };
  const num = sentences.reduce((sum, s) => sum + s.truth * s.seconds, 0);
  const value = Math.round(num / weight);
  const parts = sentences.map((s) => `${s.truth}×${s.seconds}`).join(" + ");
  return {
    rollup: value,
    formula: `${value} = (${parts}) / ${weight} ${sentences.every((s) => s.seconds === sentences[0]?.seconds) ? "equal weights" : "seconds"}`,
  };
}

export function readFromLines(input: {
  id: string;
  title: string;
  speaker: string;
  kind: StudioRead["kind"];
  sourceUrl?: string;
  lines: { text: string; seconds?: number; clock?: string; deskNote?: string; oldStudio?: string }[];
}): StudioRead {
  const sentences: SentenceRead[] = input.lines.map((line, i) => {
    const scored = scoreSentence(line.text, line.seconds ?? 20);
    return {
      ...scored,
      id: `${input.id}-${i}`,
      clock: line.clock,
      deskNote: line.deskNote,
      oldStudio: line.oldStudio,
    };
  });
  const rolled = rollup(sentences);
  return {
    id: input.id,
    title: input.title,
    speaker: input.speaker,
    kind: input.kind,
    sourceUrl: input.sourceUrl,
    sentences,
    rollup: rolled.rollup,
    formula: rolled.formula,
  };
}

export function readFromText(input: {
  id: string;
  title: string;
  speaker: string;
  kind: StudioRead["kind"];

  sourceUrl?: string;
  text: string;
}): StudioRead {
  const lines = splitSentences(input.text);
  if (!lines.length) {
    return {
      id: input.id,
      title: input.title,
      speaker: input.speaker,
      kind: input.kind,
      sourceUrl: input.sourceUrl,
      sentences: [],
      rollup: 0,
      formula: "Need at least one sentence of 40 characters.",
    };
  }
  return readFromLines({ ...input, lines: lines.map((text) => ({ text })) });
}

function bag(text: string) {
  return new Set(
    text
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, " ")
      .split(/\s+/)
      .filter((w) => w.length > 3),
  );
}

function jaccard(a: Set<string>, b: Set<string>) {
  let inter = 0;
  for (const t of a) if (b.has(t)) inter += 1;
  const union = a.size + b.size - inter;
  return union ? inter / union : 0;
}

export function diffOutlets(a: string[], b: string[]): OutletDiff {
  const used = new Set<number>();
  const both: string[] = [];
  const onlyA: string[] = [];
  for (const left of a) {
    const leftBag = bag(left);
    let best = -1;
    let bestScore = 0;
    b.forEach((right, i) => {
      if (used.has(i)) return;
      const score = jaccard(leftBag, bag(right));
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    });
    if (best >= 0 && bestScore >= 0.28) {
      used.add(best);
      both.push(left);
    } else {
      onlyA.push(left);
    }
  }
  const onlyB = b.filter((_, i) => !used.has(i));
  return { both, onlyA, onlyB };
}

function caseLawSection(read: StudioRead): string[] {
  const hits = read.sentences.flatMap((s, i) => s.caseLaw.map((c) => ({ i, text: s.text, c })));
  if (!hits.length) return ["No case in this desk matched these sentences.", ""];
  return hits.flatMap(({ i, text, c }) => [

    lines.push("");
  }
  return lines.filter((line) => line !== "").join("\n");
}

export function downloadText(filename: string, body: string) {
  const blob = new Blob([body], { type: "text/markdown;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

