export type CaseFit = "covers" | "does not decide" | "in tension";

export type CaseLaw = {
  name: string;
  cite: string;
  href: string;
  fit: CaseFit;
  plain: string;
  holding: string;
  limit: string;
};

const FIT_LABEL: Record<CaseFit, string> = {
  covers: "This source is about the same point.",
  "does not decide": "This source is about something else.",
  "in tension": "This sentence goes further than the source allows.",
};

export function fitLabel(fit: CaseFit) {
  return FIT_LABEL[fit];
}

type Authority = {
  name: string;
  cite: string;
  href: string;
  plain: string;
  holding: string;
  limit: string;
  test: RegExp;
  fit: (text: string) => CaseFit;
};

const AUTHORITIES: Authority[] = [
  {
    name: "Arizona v. United States",
    cite: "567 U.S. 387 (2012)",
    href: "https://www.supremecourt.gov/opinions/11pdf/11-182.pdf",
    plain: "The Court said Arizona could not write its own crimes for immigration paperwork, for working without federal permission, or for arresting people just because they might be removable.",
    holding: "Three pieces of S.B. 1070 were blocked. A status check during a lawful stop was left in place, on its face.",
    limit: "It does not say a mayor commits a felony for not calling ICE. It is not a voting case.",
    test: /arizona v|567 u\.s\. 387|s\.?\s*b\.?\s*1070|§\s*1357|8 u\.?\s*s\.?\s*code §\s*1357|federal immigration officers|immigration preemption|alien registration/i,
    fit: (text) => {
      if (/ballot|mail-in/i.test(text) && !/immigration|registration|1357/i.test(text)) return "does not decide";
      if (/charged personally|harboring|notify ice|detainer/i.test(text)) return "does not decide";
      return "covers";
    },
  },
  {
    name: "Printz v. United States",
    cite: "521 U.S. 898 (1997)",

    cite: "Nothing in this desk",
    href: "https://www.supremecourt.gov/opinions/opinions.aspx",
    plain: "This desk has no case that says the Supreme Court banned mail-in ballots in every state.",
    holding: "Arizona v. United States is about immigration, not ballots.",
    limit: "A cable line is not an emergency order. Read the docket before repeating one.",
    test: /banned every mail-in|mail-in ballot in every state/i,
    fit: () => "in tension",
  },
];

const FIT_RANK: Record<CaseFit, number> = { "in tension": 0, "does not decide": 1, covers: 2 };

export function applyCaseLaw(text: string): CaseLaw[] {
  return AUTHORITIES.filter((row) => row.test.test(text))
    .map((row) => ({
      name: row.name,
      cite: row.cite,
      href: row.href,
      fit: row.fit(text),
      plain: row.plain,
      holding: row.holding,
      limit: row.limit,
    }))
    .sort((a, b) => FIT_RANK[a.fit] - FIT_RANK[b.fit])
    .slice(0, 5);
}

import { createServerFn } from "@tanstack/react-start";
import { scoreSentence } from "@/lib/engine";
import { regionEdition, regionId, regionQuery } from "@/lib/regions";

export type MidtermItem = {
  id: string;
  lane: string;
  title: string;
  outlet: string;
  href: string;
  published: string;
  at: number;
  truth: number;
};

export type MidtermDesk = {
  lanes: { name: string; items: MidtermItem[] }[];
};

const FEEDS: { lane: string; query: string }[] = [
  {
    lane: "Congress",
    query: '(midterm OR midterms OR "2026 election") (Senate OR House OR Congress) when:7d',
  },
  {
    lane: "Senate",
    query: '("Senate race" OR "Senate poll" OR "U.S. Senate") 2026 when:7d',
  },
  {
    lane: "Governors",
    query: '(gubernatorial OR "governor\'s race" OR "governor race") (Texas OR Florida OR California OR Georgia OR Arizona OR Oregon) when:7d',
  },
];

const SKIP = /\b(fellows program|user clip|horoscope|box score|how to watch|starting xi)\b/i;

function decode(raw: string) {
  const named: Record<string, string> = { nbsp: " ", amp: "&", quot: '"', apos: "'", lt: "<", gt: ">" };
  return raw
    .replace(/&#(\d+);/g, (_, n: string) => String.fromCharCode(Number(n)))
    .replace(/&([a-z]+);/gi, (whole, name: string) => named[name.toLowerCase()] ?? whole)
    .replace(/\s+/g, " ")
    .trim();
}

function pick(block: string, tag: string) {
  const match = block.match(new RegExp(`<${tag}[^>]*>(?:<!\\[CDATA\\[)?([\\s\\S]*?)(?:\\]\\]>)?<\\/${tag}>`, "i"));
  return decode(match?.[1] ?? "");
}

function isFresh(published: string, hours: number) {
  const time = Date.parse(published);
  if (Number.isNaN(time)) return false;
  return Date.now() - time <= hours * 60 * 60 * 1000;
}

function stamp(published: string) {
  const time = Date.parse(published);

  if (Number.isNaN(time)) return published;
  return new Date(time).toLocaleDateString("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
}

function parseLane(xml: string, lane: string, seen: Set<string>, hours: number): MidtermItem[] {
  const blocks = xml.match(/<item>[\s\S]*?<\/item>/gi) ?? [];
  const items: MidtermItem[] = [];
  for (const block of blocks) {
    const published = pick(block, "pubDate");
    if (!isFresh(published, hours)) continue;
    const outlet = pick(block, "source");
    let title = pick(block, "title");
    if (outlet && title.endsWith(` - ${outlet}`)) title = title.slice(0, -(` - ${outlet}`.length)).trim();
    if (title.length < 36 || SKIP.test(title)) continue;
    const key = title.toLowerCase();
    if (seen.has(key)) continue;
    const href = pick(block, "link");
    if (!href.startsWith("http")) continue;
    seen.add(key);
    items.push({
      id: `${lane}-${items.length}`,
      lane,
      title,
      outlet: outlet || "News",
      href,
      published: stamp(published),
      at: Date.parse(published),
      truth: scoreSentence(title, 20).truth,
    });
    if (items.length === 5) break;
  }
  return items;
}

export const loadMidterms = createServerFn({ method: "GET" })
  .validator((input: { region?: unknown } | undefined) => ({ region: regionId(input?.region) }))
  .handler(async ({ data }): Promise<MidtermDesk> => {
  const seen = new Set<string>();
  const place = regionQuery(data.region);
  const feeds =
    data.region === "us"
      ? FEEDS
      : [
          { lane: "Government", query: `${place} (government OR parliament OR president OR prime minister) when:14d` },
          { lane: "Court", query: `${place} (court OR ruling OR judge OR trial) when:14d` },

          { lane: "Vote", query: `${place} (election OR vote OR ballot OR poll) when:14d` },
        ];
  const hours = data.region === "us" ? 24 : 24 * 7;
  const settled = await Promise.allSettled(
    feeds.map(async (feed) => {
      const url = `https://news.google.com/rss/search?${regionEdition(data.region)}&q=${encodeURIComponent(feed.query)}`;
      const res = await fetch(url, {
        redirect: "follow",
        signal: AbortSignal.timeout(12000),
        headers: {
          "user-agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36",
          accept: "application/rss+xml, application/xml, text/xml",
        },
      });
      if (!res.ok) return { name: feed.lane, items: [] as MidtermItem[] };
      return { name: feed.lane, items: parseLane(await res.text(), feed.lane, seen, hours) };
    }),
  );
  const lanes = settled.flatMap((result) => (result.status === "fulfilled" && result.value.items.length ? [result.value] : []));
  if (!lanes.length && data.region !== "us") {
    const url = `https://news.google.com/rss/search?${regionEdition(data.region)}&q=${encodeURIComponent(`${place} (government OR election OR court) when:14d`)}`;
    const res = await fetch(url, {
      redirect: "follow",
      signal: AbortSignal.timeout(12000),
      headers: {
        "user-agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36",
        accept: "application/rss+xml, application/xml, text/xml",
      },
    });
    if (res.ok) {
      const items = parseLane(await res.text(), "Government", seen, hours);
      if (items.length) lanes.push({ name: "Government", items });
    }
  }
  return { lanes };
});

