function tidy(value: string) {
  return value.replace(/\s+/g, " ").trim();
}

function sameLine(a: string, b: string) {
  return tidy(a).replace(/[.!?]+$/g, "").toLowerCase() === tidy(b).replace(/[.!?]+$/g, "").toLowerCase();
}

export function storyParts(title: string, summary: string) {
  const head = tidy(title);
  const raw = tidy(summary || "");
  const body = !raw || sameLine(raw, head) ? "" : raw;
  return { head, body };
}

export function storyCaption(title: string, summary: string) {
  const { head, body } = storyParts(title, summary);
  return body ? `${head}\n\n${body}\n\nVibeTok Clinic` : `${head}\n\nVibeTok Clinic`;
}

function loadLogo() {
  return new Promise<HTMLImageElement | null>((resolve) => {
    const img = new Image();
    img.onload = () => resolve(img.width ? img : null);
    img.onerror = () => resolve(null);
    img.src = `data:image/jpeg;base64,${MARK}`;
  });
}

const logoReady = typeof window === "undefined" ? Promise.resolve(null) : loadLogo();

function wrap(ctx: CanvasRenderingContext2D, text: string, max: number, limit: number) {
  const words = tidy(text).split(" ").filter(Boolean);
  const lines: string[] = [];
  let line = "";
  for (const word of words) {
    const next = line ? `${line} ${word}` : word;
    if (ctx.measureText(next).width > max && line) {
      lines.push(line);
      line = word;
      if (lines.length === limit) break;
    } else {
      line = next;
    }
  }
  if (line && lines.length < limit) lines.push(line);
  const used = lines.join(" ").split(" ").length;
  if (lines.length === limit && used < words.length) {
    const last = lines[lines.length - 1] ?? "";
    lines[lines.length - 1] = last.replace(/\s+\S*$/, "…");
  }
  return lines;
}

export async function storyCardFile(title: string, summary: string) {
  const { head, body } = storyParts(title, summary);
  const logo = await logoReady;
  const canvas = document.createElement("canvas");
  canvas.width = 1080;
  canvas.height = 1350;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("This browser cannot format the card.");
  ctx.fillStyle = "#f6f3ec";
  ctx.fillRect(0, 0, 1080, 1350);
  ctx.fillStyle = "#0b1220";
  ctx.fillRect(0, 0, 1080, 240);
  if (logo) ctx.drawImage(logo, 56, 48, 144, 144);
  ctx.fillStyle = "#f4efe4";
  ctx.font = "700 62px Georgia, serif";
  ctx.textAlign = "left";
  ctx.fillText("VibeTok", 224, 118);
  ctx.fillStyle = "#e4b86a";
  ctx.font = "600 22px system-ui, sans-serif";
  ctx.fillText("CLINIC", 228, 158);
  ctx.fillStyle = "#8a5e22";
  ctx.font = "600 22px system-ui, sans-serif";
  ctx.fillText("DESK NOTE", 64, 312);
  ctx.fillStyle = "#1a1d23";
  ctx.font = "700 52px Georgia, serif";
  let y = 392;
  for (const line of wrap(ctx, head, 952, 5)) {
    ctx.fillText(line, 64, y);
    y += 66;
  }
  y += 12;
  ctx.strokeStyle = "#e4b86a";
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(64, y);
  ctx.lineTo(176, y);
  ctx.stroke();
  y += 52;
  if (body) {
    ctx.fillStyle = "#1a1d23";
    ctx.font = "400 32px Georgia, serif";
    for (const line of wrap(ctx, body, 952, 10)) {
      if (y > 1160) break;
      ctx.fillText(line, 64, y);
      y += 46;
    }
  }
  ctx.fillStyle = "#0b1220";
  ctx.fillRect(0, 1230, 1080, 120);
  if (logo) ctx.drawImage(logo, 48, 1254, 72, 72);
  ctx.fillStyle = "#e4b86a";
  ctx.font = "600 26px system-ui, sans-serif";
  ctx.fillText("Written by Vibe   \u00b7   VibeTok Clinic", 140, 1300);

  const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, "image/jpeg", 0.92));
  if (!blob) throw new Error("The card could not be saved.");
  return new File([blob], "vibetok-desk-note.jpg", { type: "image/jpeg" });
}

import { changeLine } from "./vibe-execute.ts";

export function onlyMath(question: string) {
  const trimmed = question.trim().replace(/[?.!]+$/g, "");
  const spoken = trimmed.replace(/^(what is|what's|calculate|compute|evaluate)\s+/i, "");
  if (!/^[\d\s,.+\-*/×÷x()]+$/.test(spoken)) return "";
  if (!/\d/.test(spoken) || !/[+\-*/×÷x]/.test(spoken)) return "";
  const expr = spoken.replace(/×/g, "*").replace(/÷/g, "/").replace(/x/gi, "*").replace(/,/g, "");
  if (!/^[\d\s.+\-*/()]+$/.test(expr)) return "";
  try {
    const value = Function(`"use strict"; return (${expr})`)() as unknown;
    if (typeof value !== "number" || !Number.isFinite(value)) return "";
    return `${spoken} = ${value}. Calculated. This was not estimated.`;
  } catch {
    return "";
  }
}

export function resourcePlan(question: string) {
  const topic = /\b(energy|power|battery|storage|generator|solar|wind|grid|water|fuel|mwh|gwh|twh|megawatt|gigawatt|\bmw\b|\bgw\b|transmission)\b/i.test(question);
  const job = /\b(feasib|surviv|outage|reliab|backup|reserve|peak|storage|battery|grid|design|siz|enough|adequa)\b/i.test(question);
  return topic && job && /\d/.test(question);
}

export function hardProblem(question: string) {
  const task = /\b(calculat\w*|comput\w*|design\w*|sizing|size|simulat\w*|stress[-\s]?tests?|optimi[sz]\w*|allocat\w*|budgets?|shortfalls?|trade-?offs?|feasib\w*|deficits?)\b/i.test(question);
  const compare = /\bcompare\b/i.test(question) && /\b(cost|option|design|scenario|architectur|plan|system|budget)\b/i.test(question);
  const measured = /\d[\d,]*(?:\.\d+)?\s*(?:%|kwh|mwh|gwh|twh|kw|mw|gw|kcal|lit(?:er|re)s?|\bl\b|m3|m³|\$|billion|million|people|persons|hours?|days?)/i.test(question);
  return (task || compare) && measured;
}

function people(question: string) {

  const labeled = question.match(/population:\s*([\d,]+(?:\.\d+)?)\s*(million|billion)?/i);
  if (labeled) {
    const value = Number(labeled[1].replace(/,/g, ""));
    if (/million/i.test(labeled[2] || "")) return value * 1_000_000;
    if (/billion/i.test(labeled[2] || "")) return value * 1_000_000_000;
    return value;
  }
  const words = question.match(/([\d,.]+)\s*million\s+(?:people|persons|households|homes)\b/i);
  if (words) return Number(words[1].replace(/,/g, "")) * 1_000_000;
  const plain = question.match(/([\d,]+)\s*(?:people|persons|households|homes)\b/i);
  return plain ? Number(plain[1].replace(/,/g, "")) : 0;
}

type Base = { name: string; value: number; unit: string };

export function workedFigures(question: string) {
  if (!hardProblem(question)) return "";
  const lines: string[] = [];
  const bases: Base[] = [];
  const count = people(question);
  const popRate = question.match(/population growth:\s*([\d.]+)\s*%\s*(?:\/|\s*per\s+)?year/i);
  if (count > 0 && popRate) {
    const next = Math.round(count * (1 + Number(popRate[1]) / 100));
    lines.push(`Population after 1 year = ${count} × (1 + ${Number(popRate[1]) / 100}) = ${next}. Calculated.`);
  }
  const per = /([A-Za-z][A-Za-z \-]{0,24})[:\s]{0,4}([\d,]+(?:\.\d+)?)\s*([A-Za-z][A-Za-z%]{0,12})\s*(?:\/|\s+per\s+)\s*(?:person|household|capita)(?:\s*(?:\/|\s+per\s+)\s*(day|year))?/gi;
  for (const hit of question.matchAll(per)) {
    const label = (hit[1] || hit[3] || "amount").trim().toLowerCase();
    const each = Number(hit[2].replace(/,/g, ""));
    const unit = hit[3];
    const period = (hit[4] || "day").toLowerCase();
    if (!(count > 0) || !(each > 0)) continue;
    const total = count * each;

  const words = label.split(/\s+/).filter((word) => word.length > 2 && !/consumption|requirement|demand|available|production/.test(word));
  const name = words[0] || unit.toLowerCase();
  lines.push(`${name} = ${count} × ${each} ${unit}/${period} = ${total} ${unit}/${period}. Calculated.`);
  bases.push({ name, value: total, unit: `${unit}/${period}` });
  if (period === "day") {
    lines.push(`${name} per year = ${total} × 365 = ${total * 365} ${unit}/year. Calculated.`);
  }
}
const annual = question.match(/([\d,.]+)\s*(twh|gwh|mwh|kwh)\s*(?:\/|\s+per\s+)\s*year/i);
if (annual) {
  const amount = Number(annual[1].replace(/,/g, ""));
  const unit = annual[2].toLowerCase();
  const kwh = unit === "twh" ? amount * 1e9 : unit === "gwh" ? amount * 1e6 : unit === "mwh" ? amount * 1e3 : amount;
  const gw = kwh / 8760 / 1e6;
  lines.push(`Average power = ${amount} ${unit.toUpperCase()}/year ÷ 8,760 h = ${gw.toFixed(3)} GW. Calculated. This is not a peak.`);
  bases.push({ name: "electricity", value: unit === "twh" ? amount : kwh / 1e9, unit: "TWh/year" });
}
for (const hit of question.matchAll(/([\d.]+)\s*%\s*of\s+([a-z][a-z \-]{2,48})/gi)) {
  const about = hit[2].toLowerCase();
  const base = bases.find((row) => about.includes(row.name));
  if (!base) continue;
  const part = base.value * (Number(hit[1]) / 100);
  const stop = new Set(["comes", "from", "with", "that", "this", "into", "over", "than", "after", "before"]);
  const name = about.split(/\s+/).filter((word) => word.length > 3 && word !== base.name && !stop.has(word)).pop() || "share";
  lines.push(`${hit[1]}% of ${base.name} = ${part} ${base.unit}. Calculated.`);
  bases.push({ name, value: part, unit: base.unit });
}

for (const hit of question.matchAll(/([\d.]+)\s*%\s*(increase|reduction|decrease|cut)\s+in\s+([a-z][a-z \-]{2,40})/gi)) {
  const down = /reduc|decreas|cut/i.test(hit[2]);
  const about = hit[3].toLowerCase();
  const base = bases.find((row) => about.includes(row.name) || row.name.includes(about.split(/\s+/)[0] || ""));
  if (!base) {
    lines.push(`A ${hit[1]}% ${hit[2]} in ${hit[3].trim()} was stated. No base amount for that item was given, so the new total is Unknown.`);
    continue;
  }
  const next = changeLine(base.name, base.value, base.unit, hit[3], Number(hit[1]), down);
  lines.push(next);
}
for (const hit of question.matchAll(/([a-z][a-z \-]{2,32})\s+(falls?|drops?|declines?|rises?|increases?)\s+(?:by\s+)?([\d.]+)\s*%/gi)) {
  const about = hit[1].toLowerCase();
  const pct = Number(hit[3]) / 100;
  const down = /fall|drop|declin/i.test(hit[2]);
  const base = bases.find((row) => about.includes(row.name) || row.name.includes(about.split(/\s+/)[0] || ""));
  if (!base || !(pct >= 0)) {
    lines.push(`${hit[1].trim()} ${hit[2]} ${hit[3]}%. No base amount was given, so the new total is UNKNOWN.`);
    continue;
  }
  const next = changeLine(base.name, base.value, base.unit, `${hit[1].trim()} ${hit[2]} ${hit[3]}%`, Number(hit[3]), down);
  lines.push(`Shock: ${next} One event only.`);
}
const reliability = question.match(/\b(99(?:\.\d+)?)\s*%/);
if (reliability && /reliab|availab/i.test(question)) {
  const allowed = 8760 * (1 - Number(reliability[1]) / 100);
  lines.push(`A ${reliability[1]}% year allows about ${allowed.toFixed(3)} hours of outage. Calculated. This does not prove a design meets it.`);
}
if (resourcePlan(question)) {

    lines.push("Energy adequacy is not feasibility. Mark energy, peak power, battery energy, battery power, generator, transmission, and reliability each as PASS, FAIL, CONDITIONAL, or UNKNOWN. A missing discharge MW is UNKNOWN, not PASS. End with FEASIBLE, CONDITIONALLY FEASIBLE, NOT FEASIBLE, or FEASIBILITY NOT DEMONSTRATED.");
  }
  return lines.length ? `Calculator. Copy these figures in every scenario. Do not replace a figure with the words calculate, evaluate, assess, or determine.\n${lines.join("\n")}` : "";
}

import { createServerFn } from "@tanstack/react-start";
import { scoreSentence } from "@/lib/engine";
import { regionEdition, regionId, regionQuery, type RegionId } from "@/lib/regions";

export type MajorItem = {
  id: string;
  lane: string;
  title: string;
  outlet: string;
  href: string;
  published: string;
  at: number;
  truth: number;
};

export type MajorDesk = {
  lanes: { name: string; items: MajorItem[] }[];
};

const LANES = ["Nation", "World", "Politics", "Business", "Technology", "Health"] as const;

const TOPIC: Record<(typeof LANES)[number], string> = {
  Nation: "NATION",
  World: "WORLD",
  Politics: "POLITICS",
  Business: "BUSINESS",
  Technology: "TECHNOLOGY",
  Health: "HEALTH",
};

const SKIP = /\b(horoscope|box score|how to watch|starting xi|what channel)\b/i;

function decode(raw: string) {
  const named: Record<string, string> = { nbsp: " ", amp: "&", quot: '"', apos: "'", lt: "<", gt: ">" };
  return raw
    .replace(/&#(\d+);/g, (_, n: string) => String.fromCharCode(Number(n)))
    .replace(/&([a-z]+);/gi, (whole, name: string) => named[name.toLowerCase()] ?? whole)
    .replace(/\s+/g, " ")
    .trim();
}

function pick(block: string, tag: string) {
  const match = block.match(new RegExp(`<${tag}[^>]*>(?:<!\\[CDATA\\[)?([\\s\\S]*?)(?:\\]\\]>)?<\\/${tag}>`, "i"));
  return decode(match?.[1] ?? "");
}

function stamp(published: string) {
  const time = Date.parse(published);
  if (Number.isNaN(time)) return published;
  return new Date(time).toLocaleDateString("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
}

function isFresh(published: string, hours: number) {
  const time = Date.parse(published);
  if (Number.isNaN(time)) return false;
  return Date.now() - time <= hours * 60 * 60 * 1000;
}

function parseLane(xml: string, lane: string, seen: Set<string>, hours: number): MajorItem[] {
  const blocks = xml.match(/<item>[\s\S]*?<\/item>/gi) ?? [];
  const items: MajorItem[] = [];
  for (const block of blocks) {
    const published = pick(block, "pubDate");
    if (!isFresh(published, hours)) continue;
    const outlet = pick(block, "source");
    let title = pick(block, "title");
    if (outlet && title.endsWith(` - ${outlet}`)) title = title.slice(0, -(` - ${outlet}`.length)).trim();
    if (title.length < 36 || SKIP.test(title)) continue;
    const key = title.toLowerCase();
    if (seen.has(key)) continue;
    const href = pick(block, "link");
    if (!href.startsWith("http")) continue;
    seen.add(key);
    items.push({
      id: `${lane}-${items.length}`,
      lane,
      title,
      outlet: outlet || "News",
      href,
      published: stamp(published),
      at: Date.parse(published),
      truth: scoreSentence(title, 20).truth,
    });
    if (items.length === 4) break;
  }
  return items;
}

const EDITION = "hl=en-US&gl=US&ceid=US:en";

function feedUrl(region: RegionId, lane: (typeof LANES)[number]) {
  const query = laneQuery(region, lane);
  const edition = regionEdition(region);
  if (!query) return `https://news.google.com/rss/headlines/section/topic/${TOPIC[lane]}?${edition || EDITION}`;
  return `https://news.google.com/rss/search?${edition}&q=${encodeURIComponent(query)}`;
}

function laneQuery(region: RegionId, lane: (typeof LANES)[number]) {
  const place = regionQuery(region);
  if (region === "us") return "";
  if (lane === "Nation") return `${place} (government OR president OR parliament OR election OR minister) when:7d`;
  if (lane === "World") return `${place} when:7d`;
  return `${place} ${lane.toLowerCase()} when:7d`;
}

async function readFeed(url: string) {
  const res = await fetch(url, {
    redirect: "follow",
    signal: AbortSignal.timeout(12000),
    headers: {
      "user-agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36",
      accept: "application/rss+xml, application/xml, text/xml",
    },
  });
  if (!res.ok) return "";
  return res.text();
}

export const loadMajor = createServerFn({ method: "GET" })
  .validator((input: { region?: unknown } | undefined) => ({ region: regionId(input?.region) }))
  .handler(async ({ data }): Promise<MajorDesk> => {
  const seen = new Set<string>();
  const hours = data.region === "us" ? 24 : 24 * 7;
  const settled = await Promise.allSettled(
    LANES.map(async (lane) => {
      const xml = await readFeed(feedUrl(data.region, lane));
      return { name: lane, items: xml ? parseLane(xml, lane, seen, hours) : [] };
    }),
  );
  const lanes: { name: string; items: MajorItem[] }[] = settled.flatMap((result) => (result.status === "fulfilled" && result.value.items.length ? [result.value] : []));
  if (!lanes.length && data.region !== "us") {
    const place = regionQuery(data.region);
    const xml = await readFeed(`https://news.google.com/rss/search?${regionEdition(data.region)}&q=${encodeURIComponent(`${place} when:7d`)}`);
    const items = xml ? parseLane(xml, "Headlines", seen, hours) : [];
    if (items.length) lanes.push({ name: "Headlines", items });
  }
  return { lanes };
});

import { getPushPublic, removePushSubscription, savePushSubscription } from "@/lib/push.functions";

const ICON = "/__grok/icon-180.png";

export const NOTE_TITLE = "Desk Note Notification";

function urlBase64ToUint8Array(base64: string) {
  const padded = `${base64}${"=".repeat((4 - (base64.length % 4)) % 4)}`;
  const raw = atob(padded.replace(/-/g, "+").replace(/_/g, "/"));
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i += 1) out[i] = raw.charCodeAt(i);
  return out;
}

export function phoneKind(): "ios" | "android" | "other" {
  if (typeof navigator === "undefined") return "other";
  if (/iPhone|iPad|iPod/.test(navigator.userAgent)) return "ios";
  if (/Android/.test(navigator.userAgent)) return "android";
  return "other";
}

export function isInstalled() {
  if (typeof window === "undefined") return false;
  const ios = navigator as Navigator & { standalone?: boolean };
  return window.matchMedia("(display-mode: standalone)").matches || Boolean(ios.standalone);
}

export async function readyWorker() {
  if (typeof navigator === "undefined" || !("serviceWorker" in navigator)) return null;
  return navigator.serviceWorker.register("/sw.js");
}

export function notifySupport(): NotificationPermission | "unsupported" {
  if (typeof Notification === "undefined") return "unsupported";
  return Notification.permission;
}

export async function subscribePush() {
  const registration = await readyWorker();
  if (!registration?.pushManager) return false;
  const { publicKey } = await getPushPublic();
  const current = await registration.pushManager.getSubscription();
  const subscription =
    current ??
    (await registration.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: urlBase64ToUint8Array(publicKey),

    }));
  const json = subscription.toJSON();
  if (!json.endpoint || !json.keys?.p256dh || !json.keys.auth) return false;
  const saved = await savePushSubscription({
    data: { endpoint: json.endpoint, keys: { p256dh: json.keys.p256dh, auth: json.keys.auth } },
  });
  return saved.ok;
}

export async function unsubscribePush() {
  const registration = await readyWorker();
  const subscription = await registration?.pushManager?.getSubscription();
  const endpoint = subscription?.endpoint ?? "";
  if (subscription) await subscription.unsubscribe();
  if (endpoint) await removePushSubscription({ data: { endpoint } });
}

export async function askNotify() {
  await readyWorker();
  if (typeof Notification === "undefined") return "unsupported" as const;
  return Notification.requestPermission();
}

async function postNote(body: string, tag: string) {
  if (typeof Notification === "undefined" || Notification.permission !== "granted") return;
  const registration = await readyWorker();
  if (registration) {
    await registration.showNotification(NOTE_TITLE, {
      body,
      tag,
      icon: ICON,
      data: { url: "/" },
    });
    return;
  }
  const note = new Notification(NOTE_TITLE, { body, tag });
  note.onclick = () => {
    window.focus();
    note.close();
  };
}

export function sendDeskNote(body: string) {
  return postNote(body, "desk-note-status");
}

export async function sendBreaking(items: { title: string; outlet: string }[]) {
  for (const item of items) {
    const tag = `desk-note-${item.title.slice(0, 80)}`;
    await postNote(`Breaking · ${item.outlet}: ${item.title}`, tag);
  }
}

