  embed: string;
};

const STOP = new Set(["with", "from", "that", "this", "after", "over", "into", "about", "their", "have", "been", "will", "says", "said", "news", "holds", "campaign"]);

function words(value: string) {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .split(/\s+/)
    .filter((word) => word.length >= 4 && !STOP.has(word));
}

const JUNK = /\b(compilation|top stories|headlines today|daily news|news mix|news shorts|in 60 seconds)\b/i;

function echoes(query: string, title: string) {
  const source = words(query);
  if (source.length < 4) return false;
  const clipWords = new Set(words(title));
  const hit = source.filter((word) => clipWords.has(word)).length;
  return hit / source.length >= 0.75;
}

function decodeTitle(raw: string) {
  try {
    return JSON.parse(`"${raw}"`) as string;
  } catch {
    return raw;
  }
}

export const findClips = createServerFn({ method: "POST" })
  .validator((data: { title: string }) => data)
  .handler(async ({ data }): Promise<Clip[]> => {
    const query = data.title.replace(/\s+/g, " ").trim().slice(0, 140);
    if (query.length < 12) return [];
    const url = `https://www.youtube.com/results?search_query=${encodeURIComponent(query)}`;
    const res = await fetch(url, {
      redirect: "follow",
      signal: AbortSignal.timeout(12000),
      headers: {
        "user-agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36",
        accept: "text/html",
      },
    });
    if (!res.ok) return [];
    const html = (await res.text()).slice(0, 1_800_000);
    const wanted = new Set(words(query));

  if (!wanted.size) return [];
  const seen = new Set<string>();
  const found: { id: string; title: string; overlap: number }[] = [];
  for (const match of html.matchAll(/"videoId":"([\w-]{11})"/g)) {
    const id = match[1];
    if (seen.has(id)) continue;
    const window = html.slice(match.index ?? 0, (match.index ?? 0) + 1200);
    const titleMatch = window.match(/"title":\{"runs":\[\{"text":"((?:\\.|[^"\\])*)"/);
    if (!titleMatch) continue;
    const title = decodeTitle(titleMatch[1]).replace(/\s+/g, " ").trim();
    if (title.length < 12 || JUNK.test(title) || echoes(query, title)) continue;
    seen.add(id);
    const overlap = words(title).filter((word) => wanted.has(word)).length;
    if (overlap < 2) continue;
    found.push({ id, title, overlap });
    if (seen.size > 40) break;
  }
  return found
    .sort((a, b) => b.overlap - a.overlap)
    .slice(0, 4)
    .map((clip) => ({
      id: clip.id,
      title: clip.title,
      href: `https://www.youtube.com/watch?v=${clip.id}`,
      embed: `https://www.youtube-nocookie.com/embed/${clip.id}?rel=0`,
    }));
});

import { createMiddleware, createServerFn } from "@tanstack/react-start";
import { authMiddleware } from "@/lib/auth/middleware";
import { getSql } from "@/lib/db";
import { storyKey } from "@/lib/notes.functions";

const KINDS = ["like", "repost", "study"] as const;
type Kind = (typeof KINDS)[number];

const withBearer = createMiddleware({ type: "function" })
  .client(async ({ next }) => {
    const { getBearerToken } = await import("@/lib/auth/client");
    return next({ sendContext: { bearerToken: getBearerToken() ?? undefined } });
  })
  .server(async ({ next }) => next());

function empty() {
  return { like: 0, repost: 0, study: 0, mine: { like: false, repost: false, study: false } };
}

async function counts(title: string, userId: string | null) {
  const key = storyKey(title);
  if (!key) return empty();
  const sql = await getSql();
  const rows = await sql<{ kind: Kind; user_id: string }>`
    select kind, user_id from story_marks where story_key = ${key}
  `;
  const result = empty();
  for (const row of rows) {
    if (row.kind !== "like" && row.kind !== "repost" && row.kind !== "study") continue;
    result[row.kind] += 1;
    if (userId && row.user_id === userId) result.mine[row.kind] = true;
  }
  return result;
}

export const listMarks = createServerFn({ method: "GET" })
  .middleware([withBearer])
  .validator((data: { title: string }) => data)
  .handler(async ({ data, context }) => {
    const { getSessionUser } = await import("@/lib/auth/verify.server");
    const user = await getSessionUser(context.bearerToken);
    return counts(data.title, user?.id ?? null);
  });

export const toggleMark = createServerFn({ method: "POST" })
  .middleware([authMiddleware])
  .validator((data: { title: string; kind: Kind }) => data)

.handler(async ({ data, context }) => {
  if (!KINDS.includes(data.kind)) throw new Error("That action is not on the desk.");
  const key = storyKey(data.title);
  if (!key) throw new Error("This story has no title.");
  const sql = await getSql();
  const existing = await sql<{ kind: string }>`
    select kind from story_marks where story_key = ${key} and user_id = ${context.userId} and kind = ${data.kind} limit 1
  `;
  if (existing.length) {
    await sql`delete from story_marks where story_key = ${key} and user_id = ${context.userId} and kind = ${data.kind}`;
  } else {
    await sql`insert into story_marks (story_key, user_id, kind) values (${key}, ${context.userId}, ${data.kind})`;
  }
  return counts(data.title, context.userId);
});

