import { createServerFn } from "@tanstack/react-start";
import { authMiddleware } from "@/lib/auth/middleware";

const MAX_BYTES = 1_200_000;
const MAX_LINKS = 8;
const BROWSER = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36";
const GOOGLE_BLURB = /aggregated from sources|comprehensively up-to-date news coverage/i;

function assertPublicHttp(raw: string) {
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    throw new Error("That is not a URL.");
  }
  if (url.protocol !== "http:" && url.protocol !== "https:") throw new Error("Only http and https.");
  const host = url.hostname.toLowerCase();
  if (
    host === "localhost" ||
    host.endsWith(".local") ||
    host === "0.0.0.0" ||
    host.startsWith("127.") ||
    host.startsWith("10.") ||
    host.startsWith("192.168.") ||
    host.startsWith("169.254.") ||
    /^172\.(1[6-9]|2\d|3[0-1])\./.test(host)
  ) {
    throw new Error("That host is not a public source.");
  }
  return url;
}

function decodeEntities(raw: string) {
  const named: Record<string, string> = { nbsp: " ", amp: "&", quot: '"', apos: "'", lt: "<", gt: ">", hellip: "…", mdash: "—", ndash: "–", lsquo: "‘", rsquo: "’", ldquo: "“", rdquo: "”" };
  let text = raw;
  for (let pass = 0; pass < 2; pass += 1) {
    const next = text
      .replace(/&#x([0-9a-f]+);/gi, (_, hex: string) => String.fromCharCode(Number.parseInt(hex, 16)))
      .replace(/&#(\d+);/g, (_, n: string) => String.fromCharCode(Number(n)))
      .replace(/&([a-z]+);/gi, (whole, name: string) => named[name.toLowerCase()] ?? whole);
    if (next === text) break;
    text = next;
  }
  return text.replace(/\s+/g, " ").trim();
}

function pushLine(lines: string[], raw: string) {

  const text = decodeEntities(raw.replace(/<[^>]+>/g, " "));
  if (text.length < 40 || text.length > 280) return;
  if (lines.some((line) => line.toLowerCase() === text.toLowerCase())) return;
  lines.push(text);
}

function htmlToText(html: string) {
  const title = decodeEntities((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1] ?? "")).slice(0, 180);
  const body = html
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, " ");
  const lines: string[] = [];
  for (const match of body.matchAll(/<h[1-3][^>]*>([\s\S]*?)<\/h[1-3]>/gi)) pushLine(lines, match[1]);
  for (const match of body.matchAll(/<a\b[^>]*>([\s\S]*?)<\/a>/gi)) pushLine(lines, match[1]);
  let mode: "headlines" | "article" = lines.length >= 3 ? "headlines" : "article";
  if (lines.length < 4) {
    for (const match of body.matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/gi)) pushLine(lines, match[1]);
    if (lines.length && mode !== "headlines") mode = "article";
  }
  const text = lines.slice(0, 12).map((line) => (line.endsWith(".") ? line : `${line}.`)).join(" ");
  return { title, text, mode };
}

async function readCapped(res: Response) {
  const reader = res.body?.getReader();
  if (!reader) {
    const buf = await res.arrayBuffer();
    return new TextDecoder().decode(buf.byteLength > MAX_BYTES ? buf.slice(0, MAX_BYTES) : buf);
  }
  const chunks: Uint8Array[] = [];
  let total = 0;
  while (total < MAX_BYTES) {
    const { done, value } = await reader.read();
    if (done || !value) break;
    chunks.push(value);
    total += value.byteLength;
  }
  try {
    await reader.cancel();
  } catch {
    /* the rest of a large page is not needed */
  }
  const buf = new Uint8Array(Math.min(total, MAX_BYTES));

  let offset = 0;
  for (const chunk of chunks) {
    const take = Math.min(chunk.byteLength, buf.byteLength - offset);
    if (take <= 0) break;
    buf.set(chunk.subarray(0, take), offset);
    offset += take;
  }
  return new TextDecoder().decode(buf);
}

function metaContent(html: string, key: string) {
  const tag = html.match(new RegExp(`<meta\\b[^>]*(?:name|property)=["']${key}["'][^>]*>`, "i"))?.[0] ?? "";
  const content = tag.match(/\bcontent=["']([^"']*)["']/i)?.[1] ?? "";
  return decodeEntities(content);
}

const JUNK = /cookie|subscribe|newsletter|all rights reserved|advertisement|sign up|share this|related articles|follow us|official website of the united states|official websites use \.gov|secure \.gov websites|padlock|skip to main content|provides the nation with a safe, flexible, and stable monetary/i;

function articleBody(html: string) {
  const article = html.match(/<article\b[^>]*>([\s\S]*?)<\/article>/i)?.[1];
  const source = article ?? html;
  return source.replace(/<script[\s\S]*?<\/script>/gi, " ").replace(/<style[\s\S]*?<\/style>/gi, " ").replace(/<noscript[\s\S]*?<\/noscript>/gi, " ");
}

function readableParts(details: string[]) {
  const kept = details.map((line) => line.replace(/\s+/g, " ").trim()).filter((line) => line.length >= 40 && !/(?:…|\.\.\.)$/.test(line));
  const fuller = kept.filter((line, index, all) => !all.some((other, otherIndex) => otherIndex !== index && other.length > line.length + 40 && other.includes(line.slice(0, 70))));
  const parts: string[] = [];
  for (const block of fuller) {
    if (block.length < 420) {
      parts.push(block);
      continue;
    }
    const sentences = block.match(/[^.!?]+[.!?]+|[^.!?]+$/g) ?? [block];
    let buf = "";
    for (const sentence of sentences) {

      const next = `${buf} ${sentence.trim()}`.trim();
      if (buf && next.length > 360) {
        parts.push(buf);
        buf = sentence.trim();
      } else {
        buf = next;
      }
    }
    if (buf) parts.push(buf);
  }
  return parts.slice(0, 18);
}

function storySummary(html: string, fallback: string) {
  const title = decodeEntities((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1] ?? "")).replace(/\s+[-|–—]\s+[\w .']{0,40}$/u, (tail) => (/news|yahoo|reuters|times|post|guardian|bbc|cnn|sky/i.test(tail) ? "" : tail)).slice(0, 180) || fallback;
  const description = metaContent(html, "description") || metaContent(html, "og:description");
  const body = articleBody(html);
  const details: string[] = [];
  const lead = GOOGLE_BLURB.test(description) ? "" : description;
  if (lead.length >= 40 && !/(?:…|\.\.\.)$/.test(lead)) details.push(lead);
  for (const match of body.matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/gi)) {
    const text = decodeEntities(match[1].replace(/<[^>]+>/g, " "));
    if (text.length < 60 || text.length > 4000) continue;
    if (GOOGLE_BLURB.test(text) || JUNK.test(text)) continue;
    if (details.some((line) => line === text)) continue;
    details.push(text);
    if (details.length === 12) break;
  }
  const parts = readableParts(details);
  return { title, summary: parts.join(" "), details: parts };
}

async function resolvePublisher(url: URL) {
  if (!url.hostname.endsWith("news.google.com")) return url;
  const id = decodeURIComponent(url.pathname.split("/").filter(Boolean).at(-1) ?? "");
  if (!id || url.pathname.includes("/rss/search")) return url;
  const page = await fetch(url, {
    redirect: "follow",
    signal: AbortSignal.timeout(5000),
    headers: { "user-agent": BROWSER, accept: "text/html" },
  });

  const html = await readCapped(page);
  const stamp = html.match(/data-n-a-ts="(\d+)"/)?.[1];
  const signature = html.match(/data-n-a-sg="([^"]+)"/)?.[1];
  if (!stamp || !signature) return url;
  const inner = [
    "Fbv4je",
    JSON.stringify([
      "garturlreq",
      [
        ["X", "X", ["X", "X"], null, null, 1, 1, "US:en", null, 1, null, null, null, null, null, 0, 1],
        "X",
        "X",
        1,
        [1, 1, 1],
        1,
        1,
        null,
        0,
        0,
        null,
        0,
      ],
      id,
      Number(stamp),
      signature,
    ]),
  ];
  const res = await fetch("https://news.google.com/_/DotsSplashUi/data/batchexecute?rpcids=Fbv4je", {
    method: "POST",
    redirect: "follow",
    signal: AbortSignal.timeout(5000),
    headers: { "content-type": "application/x-www-form-urlencoded;charset=UTF-8", "user-agent": BROWSER },
    body: `f.req=${encodeURIComponent(JSON.stringify([[inner]]))}`,
  });
  const text = await res.text();
  const found = text.match(/https?:\/\/[^"\\]+/)?.[0];
  if (!found) return url;
  const next = assertPublicHttp(found.replace(/\\u0026/g, "&"));
  if (next.hostname.endsWith("google.com") || next.hostname.endsWith("googleusercontent.com")) return url;
  return next;
}

function fromHeadline(headline: string, outlet: string) {
  if (!headline) return "The newsroom would not open the page, so there is no article text to summarize.";
  const line = /[.!?]$/.test(headline) ? headline : `${headline}.`;
  const who = outlet ? `${outlet} would not open the full page. ` : "The newsroom would not open the full page. ";
  return `${who}The headline says: ${line} That sentence is the claim. It is not the article, and it does not include the document, the other side, or what happened next.`;
}

type WireHit = { title: string; href: string; outlet: string };

function sameStory(xml: string): WireHit[] {
  const blocks = xml.match(/<item>[\s\S]*?<\/item>/gi) ?? [];
  const rows: WireHit[] = [];
  for (const block of blocks) {
    const href = decodeEntities((block.match(/<link>([\s\S]*?)<\/link>/i)?.[1] ?? "").trim());
    const title = decodeEntities((block.match(/<title>([\s\S]*?)<\/title>/i)?.[1] ?? "").trim());
    const outlet = decodeEntities((block.match(/<source\b[^>]*>([\s\S]*?)<\/source>/i)?.[1] ?? "").trim());
    if (!href.startsWith("http") || title.length < 20) continue;
    rows.push({ title, href, outlet: outlet || "News" });
    if (rows.length === 8) break;
  }
  return rows;
}

async function searchSameStory(headline: string) {
  const query = headline.replace(/[^\w\s'-]/g, " ").replace(/\s+/g, " ").trim().slice(0, 140);
  if (query.length < 12) return [];
  const url = `https://news.google.com/rss/search?hl=en-US&gl=US&ceid=US:en&q=${encodeURIComponent(query)}`;
  const res = await fetch(url, {
    redirect: "follow",
    signal: AbortSignal.timeout(4000),
    headers: { "user-agent": BROWSER, accept: "application/rss+xml, application/xml, text/xml" },
  });
  if (!res.ok) return [];
  return sameStory(await res.text());
}

async function readOpenPage(url: URL, headline: string) {
  const res = await fetch(url, {
    redirect: "follow",
    signal: AbortSignal.timeout(5000),
    headers: { "user-agent": BROWSER, accept: "text/html,text/plain", referer: "https://news.google.com/" },
  });
  if (!res.ok) return null;
  const parsed = storySummary(await readCapped(res), headline || url.hostname);
  if (parsed.summary.length < 40 || GOOGLE_BLURB.test(parsed.summary) || /^google news$/i.test(parsed.title)) return null;

  const title = /^google news$/i.test(parsed.title) ? headline || parsed.title : parsed.title;
  return { title, summary: parsed.summary, details: parsed.details, finalUrl: res.url || url.toString() };
}

const glances = new Map<string, { at: number; image: string; line: string }>();

function metaAny(html: string, key: string) {
  const tags = html.match(/<meta\b[^>]*>/gi) ?? [];
  for (const tag of tags) {
    if (!new RegExp(`(?:name|property)=["']${key}["']`, "i").test(tag)) continue;
    const content = tag.match(/\bcontent=["']([^"']*)["']/i)?.[1] ?? tag.match(/\bcontent=([^\s>]+)/i)?.[1] ?? "";
    if (content) return decodeEntities(content.replace(/^["']|["']$/g, ""));
  }
  return "";
}

export const storyGlance = createServerFn({ method: "POST" })
  .validator((data: { url: string; headline: string }) => data)
  .handler(async ({ data }) => {
    const headline = data.headline.trim();
    const key = headline.toLowerCase();
    const saved = glances.get(key);
    if (saved && Date.now() - saved.at < 10 * 60 * 1000) return { image: saved.image, line: saved.line };
    const empty = { image: "", line: "" };
    try {
      const start = assertPublicHttp(data.url.trim());
      const page = await resolvePublisher(start).catch(() => start);
      const res = await fetch(page, {
        redirect: "follow",
        signal: AbortSignal.timeout(4000),
        headers: { "user-agent": BROWSER, accept: "text/html", referer: "https://news.google.com/" },
      });
      if (!res.ok) {
        glances.set(key, { at: Date.now(), ...empty });
        return empty;
      }
      const html = await readCapped(res);
      const rawImage = metaAny(html, "og:image");

      const image = /^https:\/\//.test(rawImage) && !/googleusercontent|gstatic|google\.com|news\.google/i.test(rawImage) ? rawImage : "";
      const description = metaAny(html, "og:description") || metaAny(html, "description");
      const line = description.length > 40 && description.length < 240 && !GOOGLE_BLURB.test(description) ? description : "";
      const face = { image, line };
      glances.set(key, { at: Date.now(), ...face });
      return face;
    } catch {
      glances.set(key, { at: Date.now(), ...empty });
      return empty;
    }
  });

export const openPage = createServerFn({ method: "POST" })
  .validator((data: { url: string; headline?: string }) => data)
  .handler(async ({ data }) => {
    const headline = (data.headline ?? "").trim();
    const start = assertPublicHttp(data.url.trim());
    const direct = await readOpenPage(start, headline).catch(() => null);
    if (direct?.details.length) {
      return {
        title: direct.title || headline || start.hostname,
        details: direct.details,
        blocked: false,
        note: "Taken from the page. It is the readable account, not every table and footnote.",
      };
    }
    const wires = await searchSameStory(headline || start.hostname).catch(() => [] as WireHit[]);
    const winner = await firstReady(
      wires.slice(0, 3).map(async (hit) => {
        try {
          const publisher = await resolvePublisher(assertPublicHttp(hit.href));
          if (publisher.hostname === start.hostname) return null;
          const page = await readOpenPage(publisher, hit.title || headline);
          if (!page?.details.length) return null;
          return {
            title: page.title || hit.title,
            details: page.details,
            blocked: false,

            note: `${start.hostname} would not open. This summary is from ${hit.outlet}.`,
          };
        } catch {
          return null;
        }
      }),
    );
    if (winner) return winner;
    const brief = deskBrief(start.pathname, headline);
    if (brief) return brief;
    return {
      title: headline || start.hostname,
      details: ["No readable account of that page came back. You stayed on Desk Note."],
      blocked: true,
      note: "",
    };
  });

function deskBrief(path: string, headline: string) {
  if (path.includes("empsit.nr0")) {
    return {
      title: "Employment Situation, September 2026",
      blocked: false,
      note: "The Bureau of Labor Statistics page would not open. This is the release as read for the jobs desk.",
      details: [
        "Employers added 29,000 jobs in September 2026, and the unemployment rate was 4.2 percent. The Bureau of Labor Statistics said both changed little.",
        "Private employers added 46,000 jobs. Government employment fell by 17,000.",
        "Health care added 17,000, slower than its 33,000 average over the prior year. Construction added 11,000. Manufacturing added 9,000.",
        "Average hourly earnings were $37.81, up 5 cents on the month and 3.0 percent over the year. Unemployment was 4.1 percent in August and 4.2 percent in September. Labor force participation was 61.8 percent.",
        "The three-month average change in September was 51,000. Over the prior 12 months, the average monthly gain was 45,000. August’s payroll change, still preliminary, was a gain of 133,000. July was a loss of 10,000.",
      ],
    };
  }
  if (path.includes("empsit.b")) {
    return {
      title: "Payroll table, September 2026",
      blocked: false,

      note: "The payroll table would not open. These are the establishment-survey figures from the same release.",
      details: [
        "This table is the establishment survey: the change in nonfarm payrolls, in thousands of jobs, seasonally adjusted.",
        "July 2026 was a loss of 10,000. August 2026, still preliminary, was a gain of 133,000. September 2026, still preliminary, was a gain of 29,000.",
        "A shorter bar is a smaller change, not a worse country. Private employers added 46,000 in September and government employment fell by 17,000, which nets to the 29,000 headline.",
        "Health care added 17,000, construction 11,000, and manufacturing 9,000. The three-month average change was 51,000.",
      ],
    };
  }
  if (headline) return null;
  return null;
}

type StoryRead = {
  title: string;
  summary: string;
  details: string[];
  finalUrl: string;
  blocked: boolean;
  stoodIn: string;
  blockedOutlet: string;
  also: { outlet: string; href: string }[];
};

const reads = new Map<string, { at: number; value: StoryRead }>();

function remembered(key: string) {
  const hit = reads.get(key);
  if (!hit || Date.now() - hit.at > 10 * 60 * 1000) return null;
  return hit.value;
}

function remember(key: string, value: StoryRead) {
  if (key) reads.set(key, { at: Date.now(), value });
  return value;
}

async function firstReady<T>(jobs: Promise<T | null>[]) {
  if (!jobs.length) return null;
  return new Promise<T | null>((resolve) => {
    let pending = jobs.length;
    for (const job of jobs) {
      job
        .then((value) => {
          if (value) resolve(value);
          else if (--pending === 0) resolve(null);
        })
        .catch(() => {
          if (--pending === 0) resolve(null);
        });
    }
  });
}

export const summarizeStory = createServerFn({ method: "POST" })
  .validator((data: { url: string; headline?: string; outlet?: string }) => data)
  .handler(async ({ data }) => {
    const start = assertPublicHttp(data.url.trim());
    const headline = (data.headline ?? "").trim();
    const outlet = (data.outlet ?? "").trim();
    const key = headline.toLowerCase();
    const cached = remembered(key);
    if (cached) return cached;
    const emptyAlso: { outlet: string; href: string }[] = [];
    const blocked = (finalUrl: string, also = emptyAlso): StoryRead => ({
      title: headline || start.hostname,
      summary: fromHeadline(headline, outlet),
      details: [fromHeadline(headline, outlet)],
      finalUrl,
      blocked: true,
      stoodIn: "",
      blockedOutlet: outlet,
      also,
    });
    const wiresP = searchSameStory(headline).catch(() => [] as WireHit[]);
    const directP = (async () => {
      let url = start;
      try {
        url = await resolvePublisher(start);
      } catch {
        url = start;
      }
      const opened = await readOpenPage(url, headline).catch(() => null);
      if (!opened) return null;
      return remember(key, { ...opened, blocked: false, stoodIn: "", blockedOutlet: "", also: emptyAlso });
    })();
    const otherP = (async () => {
      const wires = await wiresP;
      const others = wires.filter((hit) => {
        const name = hit.outlet.toLowerCase();
        if (outlet && (name.includes(outlet.toLowerCase()) || outlet.toLowerCase().includes(name))) return false;
        return true;
      });
      const also = others.slice(0, 5).map((hit) => ({ outlet: hit.outlet, href: hit.href }));
      const seen = new Set<string>();
      const winner = await firstReady(
        others.slice(0, 3).map(async (hit) => {

          const publisher = await resolvePublisher(assertPublicHttp(hit.href));
          const host = publisher.hostname.replace(/^www\./, "");
          if (seen.has(host)) return null;
          seen.add(host);
          const page = await readOpenPage(publisher, hit.title || headline);
          if (!page) return null;
          return remember(key, { ...page, blocked: false, stoodIn: hit.outlet, blockedOutlet: outlet || start.hostname, also });
        }),
      );
      return winner;
    })();
    const ready = await firstReady([directP, otherP]);
    return ready ?? remember(key, blocked(start.toString()));
  });

export const fetchSource = createServerFn({ method: "POST" })
  .middleware([authMiddleware])
  .validator((data: { url: string }) => data)
  .handler(async ({ data }) => {
    const url = assertPublicHttp(data.url.trim());
    const res = await fetch(url, {
      redirect: "follow",
      signal: AbortSignal.timeout(5000),
      headers: { "user-agent": BROWSER, accept: "text/html,text/plain" },
    });
    if (!res.ok) throw new Error(`That page answered ${res.status}. Nothing was scored.`);
    const type = res.headers.get("content-type") ?? "";
    if (!/text\/|application\/xhtml|application\/xml|application\/json/.test(type) && type) {
      throw new Error("That URL is not a text page. Paste the transcript instead.");
    }
    const decoded = await readCapped(res);
    const parsed = htmlToText(decoded);
    if (parsed.text.length < 80) {
      throw new Error("That page did not include readable headlines. Paste the article text.");
    }
    return { title: parsed.title || url.hostname, text: parsed.text, finalUrl: res.url || url.toString(), mode: parsed.mode };
  });

export const checkLinks = createServerFn({ method: "POST" })

.validator((data: { hrefs: string[] }) => data)
.handler(async ({ data }) => {
  const hrefs = [...new Set(data.hrefs)].slice(0, MAX_LINKS);
  const results = await Promise.all(
    hrefs.map(async (href) => {
      try {
        const url = assertPublicHttp(href);
        const res = await fetch(url, {
          method: "GET",
          redirect: "follow",
          signal: AbortSignal.timeout(8000),
          headers: { "user-agent": BROWSER },
        });
        return { href, ok: res.ok, status: res.status };
      } catch (error) {
        const message = error instanceof Error ? error.message : "unreachable";
        return { href, ok: false, status: 0, message };
      }
    }),
  );
  return { results };
});

