const LOCAL: Record<RegionId, Board[]> = {
  us: [
    { id: "nfl", sport: "football", league: "nfl", name: "NFL", kind: "American football" },

  oceania: [{ id: "aleague", sport: "soccer", league: "aus.1", name: "A-League", kind: "Football" }],
};

const UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0.0.0 Safari/537.36";
const DAY = 24 * 60 * 60 * 1000;
const TTL = 50_000;

const saved = new Map<RegionId, { at: number; data: SportsDesk }>();
const pending = new Map<RegionId, Promise<SportsDesk>>();

function rec(value: unknown): Record<string, unknown> | null {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as Record<string, unknown>) : null;
}

function list(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}

function text(value: unknown, max = 160): string {
  return typeof value === "string" ? value.replace(/\s+/g, " ").trim().slice(0, max) : "";
}

async function readJson(url: string): Promise<unknown | null> {
  try {
    const response = await fetch(url, {
      headers: { "User-Agent": UA, Accept: "application/json" },
      signal: AbortSignal.timeout(8_000),
    });
    if (!response.ok) return null;
    return (await response.json()) as unknown;
  } catch {
    return null;
  }
}

function hrefOf(links: unknown): string {
  const web = rec(rec(links)?.web);
  const direct = text(web?.href, 400);
  if (direct.startsWith("http")) return direct.split("?")[0] ?? direct;
  for (const link of list(links)) {
    const href = text(rec(link)?.href, 400);
    if (href.startsWith("http")) return href.split("?")[0] ?? href;
  }
  return "";
}

function mp4Of(links: unknown): string {
  const root = rec(links);
  const href = text(rec(root?.source)?.href, 500) || text(rec(rec(root?.mobile)?.source)?.href, 500);
  if (!href.startsWith("https://") || !/\.mp4(\?|$)/i.test(href)) return "";

  return href.split("?")[0] ?? href;
}

function clipId(links: unknown): string {
  const api = text(rec(rec(rec(links)?.api)?.self)?.href, 240);
  const fromApi = api.match(/\/clips\/(\d+)/)?.[1];
  if (fromApi) return fromApi;
  const web = text(rec(rec(links)?.web)?.href, 240);
  return web.match(/\/id\/(\d+)/)?.[1] ?? "";
}

function freshFile(links: unknown, restrictions: unknown, now: number) {
  const exp = Date.parse(text(rec(restrictions)?.expirationDate, 40));
  if (Number.isFinite(exp) && exp < now) return "";
  return mp4Of(links);
}

const GRIM = /\b(killed|killing|dead|dies|died|murder|shot dead|robbery)\b/i;

function blankItem(row: Pick<SportsItem, "id" | "title" | "league" | "kind" | "name" | "state" | "detail" | "place" | "href" | "image" | "video" | "at">): SportsItem {
  return {
    ...row,
    pair: false,
    homeName: row.name,
    homeScore: "",
    homeLogo: "",
    homeWinner: false,
    awayName: "",
    awayScore: "",
    awayLogo: "",
    awayWinner: false,
  };
}

function stateOf(status: Record<string, unknown> | null): SportsItem["state"] {
  const state = text(rec(status?.type)?.state, 12);
  if (state === "in") return "live";
  if (state === "post") return "final";
  return "soon";
}

function detailOf(status: Record<string, unknown> | null, state: SportsItem["state"]): string {
  const type = rec(status?.type);
  const detail = text(type?.shortDetail, 48) || text(type?.detail, 48) || text(status?.displayClock, 24);
  if (detail) return detail;
  if (state === "live") return "Live";
  if (state === "final") return "Final";
  return "Scheduled";
}

function side(row: Record<string, unknown> | null) {
  const team = rec(row?.team);
  const score = text(row?.score, 32);
  return {

    name: text(team?.displayName || team?.shortDisplayName, 48),
    score: score || "–",
    logo: text(team?.logo, 240),
    winner: row?.winner === true,
  };
}

function named(name: string) {
  return Boolean(name) && name !== "None" && name !== "TBD";
}

function placeOf(event: Record<string, unknown>, comp: Record<string, unknown> | null) {
  const venue = rec(comp?.venue) ?? rec(event.venue);
  const address = rec(venue?.address);
  const name = text(venue?.fullName, 60);
  const city = text(address?.city, 40);
  return [name, city && city !== name ? city : ""].filter(Boolean).join(", ");
}

function fromBoard(board: Board, payload: unknown, now: number): SportsItem[] {
  const rows: SportsItem[] = [];
  for (const item of list(rec(payload)?.events)) {
    const event = rec(item);
    if (!event) continue;
    const comp = rec(list(event.competitions)[0]);
    const status = rec(comp?.status) ?? rec(event.status);
    const state = stateOf(status);
    const start = text(event.date, 40);
    const at = Date.parse(start);
    if (Number.isFinite(at)) {
      if (state === "final" && now - at > 72 * 60 * 60 * 1000) continue;
      if (state === "soon" && (at - now > 8 * DAY || now - at > 6 * 60 * 60 * 1000)) continue;
    }
    const competitors = list(comp?.competitors).map((row) => rec(row)).filter((row): row is Record<string, unknown> => Boolean(row));
    const ordered = [...competitors].sort((a, b) => (text(a.homeAway) === "home" ? -1 : 1) - (text(b.homeAway) === "home" ? -1 : 1));
    const home = side(ordered[0] ?? null);
    const away = ordered[1] ? side(ordered[1]) : null;
    const pair = Boolean(away) && named(home.name) && named(away!.name) && competitors.length === 2;
    const id = text(event.id, 24);
    if (!id) continue;

    const detail = detailOf(status, state);
    const name = text(event.shortName || event.name, 90) || board.name;
    const title = pair ? `${board.name}: ${away!.name} ${away!.score} at ${home.name} ${home.score}. ${detail}` : `${board.name}: ${name}. ${detail}`;
    const highlight = rec(list(comp?.highlights)[0]);
    const image = text(highlight?.thumbnail, 400);
    const video = freshFile(highlight?.links, highlight?.timeRestrictions, now);
    rows.push({
      id: `${board.id}-${id}`,
      title,
      league: board.name,
      kind: board.kind,
      name,
      state,
      detail,
      pair,
      homeName: pair ? home.name : name,
      homeScore: pair ? home.score : "",
      homeLogo: pair ? home.logo : "",
      homeWinner: pair ? home.winner : false,
      awayName: pair && away ? away.name : "",
      awayScore: pair && away ? away.score : "",
      awayLogo: pair && away ? away.logo : "",
      awayWinner: pair && away ? away.winner : false,
      place: placeOf(event, comp),
      href: hrefOf(event.links) || hrefOf(comp?.links) || `https://www.espn.com/${board.sport}/scoreboard`,
      image: image.startsWith("http") ? image : "",
      video,
      at: Number.isFinite(at) ? at : now,
    });
  }
  return rows;
}

type Clip = { id: string; title: string; league: string; kind: string; image: string; href: string; at: number };

function fromNews(board: Board, payload: unknown, now: number): { pictures: SportsItem[]; clips: Clip[] } {
  const pictures: SportsItem[] = [];
  const clips: Clip[] = [];
  for (const item of list(rec(payload)?.articles)) {
    const row = rec(item);
    if (!row) continue;
    const headline = text(row.headline, 120);
    if (!headline || GRIM.test(headline)) continue;

    const image = text(rec(list(row.images)[0])?.url, 400);
    if (!image.startsWith("https://")) continue;
    const published = Date.parse(text(row.published, 40));
    if (Number.isFinite(published) && (now - published > 120 * DAY || published > now + 60 * 60 * 1000)) continue;
    const href = hrefOf(row.links) || `https://www.espn.com/${board.sport}/`;
    const at = Number.isFinite(published) ? published : now;
    if (text(row.type, 20) === "Media") {
      const id = clipId(row.links);
      if (id && clips.length < 2) clips.push({ id, title: headline, league: board.name, kind: board.kind, image, href, at });
      continue;
    }
    if (pictures.length >= 2) continue;
    pictures.push(
      blankItem({
        id: `pic-${board.id}-${text(row.id, 24) || headline.slice(0, 16)}`,
        title: headline,
        league: board.name,
        kind: board.kind,
        name: headline,
        state: "final",
        detail: "Photo",
        place: board.name,
        href,
        image,
        video: "",
        at,
      }),
    );
  }
  return { pictures, clips };
}

async function filmFrom(clip: Clip, now: number): Promise<SportsItem | null> {
  const payload = await readJson(`https://content.core.api.espn.com/v1/video/clips/${clip.id}`);
  const video = rec(list(rec(payload)?.videos)[0]);
  if (!video) return null;
  const file = freshFile(video.links, video.timeRestrictions, now);
  const image = text(video.thumbnail, 400) || clip.image;
  if (!file && !image.startsWith("https://")) return null;
  return blankItem({
    id: `film-${clip.id}`,
    title: clip.title,
    league: clip.league,
    kind: clip.kind,
    name: clip.title,
    state: "final",
    detail: file ? "Film" : "Photo",
    place: clip.league,
    href: clip.href,

    image: image.startsWith("https://") ? image : "",
    video: file,
    at: clip.at,
  });
}

async function loadBoard(board: Board, now: number) {
  const [score, news] = await Promise.all([
    readJson(`https://site.api.espn.com/apis/site/v2/sports/${board.sport}/${board.league}/scoreboard`),
    readJson(`https://site.api.espn.com/apis/site/v2/sports/${board.sport}/${board.league}/news?limit=8`),
  ]);
  const media = news ? fromNews(board, news, now) : { pictures: [], clips: [] };
  return { matches: score ? fromBoard(board, score, now) : [], ...media };
}

async function build(region: RegionId): Promise<SportsDesk> {
  const now = Date.now();
  const boards = [...LOCAL[region], ...GLOBAL];
  const rows: SportsItem[] = [];
  const pictures: SportsItem[] = [];
  const clips: Clip[] = [];
  for (let i = 0; i < boards.length; i += 8) {
    const found = await Promise.all(boards.slice(i, i + 8).map((board) => loadBoard(board, now)));
    for (const part of found) {
      rows.push(...part.matches);
      pictures.push(...part.pictures);
      clips.push(...part.clips);
    }
  }
  const seen = new Set<string>();
  const films: SportsItem[] = [];
  for (let i = 0; i < clips.length && films.length < 8; i += 4) {
    const batch = clips.slice(i, i + 4);
    const opened = await Promise.all(batch.map((clip) => filmFrom(clip, now)));
    for (const item of opened) {
      if (!item || seen.has(item.image || item.video || item.id)) continue;
      seen.add(item.image || item.video || item.id);
      films.push(item);
      if (films.length >= 8) break;
    }
  }
  const gallery = [...films, ...pictures.filter((item) => !seen.has(item.image))].slice(0, 16);
  const rank = { live: 0, soon: 1, final: 2 };

  rows.sort((a, b) => rank[a.state] - rank[b.state] || a.league.localeCompare(b.league) || a.name.localeCompare(b.name));
  const kinds = [...new Set(rows.map((row) => row.kind))];
  const lanes = [
    ...(gallery.length ? [{ name: "Pictures and film", items: gallery }] : []),
    ...kinds.map((name) => ({ name, items: rows.filter((row) => row.kind === name) })),
  ];
  const data = { lanes };
  saved.set(region, { at: now, data });
  return data;
}

async function deskFor(region: RegionId): Promise<SportsDesk> {
  const hit = saved.get(region);
  if (hit && Date.now() - hit.at < TTL) return hit.data;
  let job = pending.get(region);
  if (!job) {
    job = build(region).finally(() => pending.delete(region));
    pending.set(region, job);
  }
  if (hit) return hit.data;
  try {
    return await job;
  } catch {
    return { lanes: [] };
  }
}

export const loadSports = createServerFn({ method: "GET" })
  .validator((input: { region?: unknown } | undefined) => ({ region: regionId(input?.region) }))
  .handler(async ({ data }): Promise<SportsDesk> => deskFor(data.region));

