function decode(raw: string) {

  const named: Record<string, string> = { nbsp: " ", amp: "&", quot: '"', apos: "'", lt: "<", gt: ">" };
  return raw
    .replace(/&#(\d+);/g, (_, n: string) => String.fromCharCode(Number(n)))
    .replace(/&([a-z]+);/gi, (whole, name: string) => named[name.toLowerCase()] ?? whole)
    .replace(/\s+/g, " ")
    .trim();
}

function pick(block: string, tag: string) {
  const match = block.match(new RegExp(`<${tag}[^>]*>(?:<!\\[CDATA\\[)?([\\s\\S]*?)(?:\\]\\]>)?<\\/${tag}>`, "i"));
  return decode(match?.[1] ?? "");
}

function iconOf(value: unknown) {
  return typeof value === "string" && value.startsWith("https://") ? value : "";
}

function daysFrom(periods: Array<{ name?: string; temperature?: number; shortForecast?: string; icon?: string }>): DayCast[] {
  const days: DayCast[] = [];
  for (const period of periods) {
    if (typeof period.temperature !== "number") continue;
    const name = String(period.name ?? "");
    const night = /night|overnight/i.test(name);
    const short = String(period.shortForecast ?? "");
    if (!night) {
      days.push({ name, high: period.temperature, low: null, short, icon: iconOf(period.icon) });
      continue;
    }
    const last = days.at(-1);
    if (last && last.low === null) last.low = period.temperature;
    else days.push({ name, high: null, low: period.temperature, short, icon: iconOf(period.icon) });
  }
  return days.slice(0, 7);
}

async function skyFor(place: string, lat: number, lon: number): Promise<Sky | null> {
  const points = await fetch(`https://api.weather.gov/points/${lat},${lon}`, {
    headers: HEADERS,
    signal: AbortSignal.timeout(8000),
  });
  if (!points.ok) return null;
  const forecastUrl = (await points.json())?.properties?.forecast as string | undefined;

  if (!forecastUrl?.startsWith("https://api.weather.gov/")) return null;
  const cast = await fetch(forecastUrl, { headers: HEADERS, signal: AbortSignal.timeout(8000) });
  if (!cast.ok) return null;
  const periods = (await cast.json())?.properties?.periods as Array<{ name?: string; temperature?: number; temperatureUnit?: string; windSpeed?: string; windDirection?: string; shortForecast?: string; detailedForecast?: string; icon?: string }> | undefined;
  const period = periods?.[0];
  if (!period || typeof period.temperature !== "number" || typeof period.shortForecast !== "string") return null;
  return {
    title: place,
    place,
    period: String(period.name ?? ""),
    temp: period.temperature,
    unit: String(period.temperatureUnit ?? "F"),
    wind: `${period.windSpeed ?? ""} ${period.windDirection ?? ""}`.trim(),
    short: period.shortForecast,
    detail: String(period.detailedForecast ?? period.shortForecast),
    icon: iconOf(period.icon),
    days: daysFrom(periods ?? []),
  };
}

async function skyOpen(place: string, lat: number, lon: number): Promise<Sky | null> {
  const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,weather_code,wind_speed_10m&daily=weather_code,temperature_2m_max,temperature_2m_min&timezone=auto&forecast_days=7`;
  const res = await fetch(url, { signal: AbortSignal.timeout(8000) });
  if (!res.ok) return null;
  const body = (await res.json()) as {
    current?: { temperature_2m?: number; weather_code?: number; wind_speed_10m?: number };
    daily?: { time?: string[]; weather_code?: number[]; temperature_2m_max?: number[]; temperature_2m_min?: number[] };
  };
  const temp = body.current?.temperature_2m;
  if (typeof temp !== "number") return null;

  const word = (code: number | undefined) => (typeof code === "number" ? CODE[code] ?? "Forecast" : "Forecast");
  const days: DayCast[] = (body.daily?.time ?? []).slice(0, 7).map((name, index) => ({
    name: new Date(`${name}T12:00:00Z`).toLocaleDateString("en-US", { weekday: "short", timeZone: "UTC" }),
    high: typeof body.daily?.temperature_2m_max?.[index] === "number" ? Math.round(body.daily.temperature_2m_max[index]) : null,
    low: typeof body.daily?.temperature_2m_min?.[index] === "number" ? Math.round(body.daily.temperature_2m_min[index]) : null,
    short: word(body.daily?.weather_code?.[index]),
    icon: "",
  }));
  const short = word(body.current?.weather_code);
  return {
    title: place,
    place,
    period: "Now",
    temp: Math.round(temp),
    unit: "C",
    wind: typeof body.current?.wind_speed_10m === "number" ? `${Math.round(body.current.wind_speed_10m)} km/h` : "",
    short,
    detail: short,
    icon: "",
    days,
  };
}
async function stories(place: string, region: RegionId): Promise<WeatherStory[]> {
  const hours = region === "us" ? 24 : 72;
  const query =
    region === "us"
      ? '(weather OR hurricane OR tornado OR storm OR flood OR wildfire) (forecast OR warning OR "National Weather Service") when:1d'
      : `${place} (weather OR storm OR flood OR heat OR rain OR cyclone OR wildfire) when:7d`;
  const url = `https://news.google.com/rss/search?${regionEdition(region)}&q=${encodeURIComponent(query)}`;
  const res = await fetch(url, {
    redirect: "follow",
    signal: AbortSignal.timeout(12000),
    headers: {
      "user-agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36",
      accept: "application/rss+xml, application/xml, text/xml",
    },
  });

  if (!res.ok) return [];
  const blocks = (await res.text()).match(/<item>[\s\S]*?<\/item>/gi) ?? [];
  const rows: WeatherStory[] = [];
  const seen = new Set<string>();
  for (const block of blocks) {
    const published = pick(block, "pubDate");
    const at = Date.parse(published);
    if (Number.isNaN(at) || Date.now() - at > hours * 60 * 60 * 1000) continue;
    const outlet = pick(block, "source");
    let title = pick(block, "title");
    if (outlet && title.endsWith(` - ${outlet}`)) title = title.slice(0, -(` - ${outlet}`.length)).trim();
    if (title.length < 36 || seen.has(title.toLowerCase())) continue;
    const href = pick(block, "link");
    if (!href.startsWith("http")) continue;
    seen.add(title.toLowerCase());
    rows.push({
      id: `weather-${rows.length}`,
      lane: "Weather",
      title,
      outlet: outlet || "News",
      href,
      published: new Date(at).toLocaleDateString("en-US", { month: "short", day: "numeric", timeZone: "UTC" }),
      at,
      truth: scoreSentence(title, 20).truth,
    });
    if (rows.length === 8) break;
  }
  return rows;
}

export const loadWeather = createServerFn({ method: "GET" })
  .validator((input: { region?: unknown } | undefined) => ({ region: regionId(input?.region) }))
  .handler(async ({ data }): Promise<WeatherDesk> => {
  const cached = saved.get(data.region);
  if (cached && Date.now() - cached.at < 15 * 60 * 1000) return cached.data;
  const cities = data.region === "us" ? CITIES : regionCities(data.region);
  const skies = await Promise.all(
    cities.map(([place, lat, lon]) => (data.region === "us" ? skyFor(place, lat, lon) : skyOpen(place, lat, lon)).catch(() => null)),
  );

  const dataDesk = { skies: skies.filter((row): row is Sky => row !== null), stories: await stories(regionQuery(data.region), data.region).catch(() => []) };
  if (!dataDesk.skies.length && !dataDesk.stories.length) throw new Error("The weather desk did not answer. Try again in a moment.");
  saved.set(data.region, { at: Date.now(), data: dataDesk });
  return dataDesk;
});

