const NAMED: Array<[RegExp, string]> = [
  [/\b(?:french|français|francais)\b/i, "French"],
  [/\b(?:german|deutsch)\b/i, "German"],
  [/\b(?:spanish|español|espanol)\b/i, "Spanish"],
  [/\b(?:portuguese|português|portugues)\b/i, "Portuguese"],
  [/\b(?:italian|italiano)\b/i, "Italian"],
  [/\b(?:dutch|nederlands)\b/i, "Dutch"],
  [/\b(?:arabic|العربية)\b/i, "Arabic"],
  [/\b(?:chinese|mandarin|中文)\b/i, "Chinese"],
  [/\b(?:japanese|日本語)\b/i, "Japanese"],
  [/\b(?:korean|한국어)\b/i, "Korean"],
  [/\b(?:hindi|हिन्दी)\b/i, "Hindi"],
  [/\b(?:russian|русский)\b/i, "Russian"],
  [/\bswahili\b/i, "Swahili"],
  [/\b(?:turkish|türkçe)\b/i, "Turkish"],
  [/\b(?:haitian|kreyòl|creole)\b/i, "Haitian Creole"],
  [/\benglish\b/i, "English"],
];

export function languageFor(question: string, chosen: string) {
  const named = question.match(/\b(?:speak|answer|respond|write|teach|instruct|explain|translate(?:\s+this)?)\s+(?:[\s\S]{0,40}?\s)?(?:in|into|to)\s+([A-Za-z\u00c0-\u024f][A-Za-z\u00c0-\u024f' -]{1,40})/i);
  if (named) {
    const spoken = named[1].replace(/\b(?:please|for me|now)\b/gi, "").trim();
    if (spoken) return spoken.slice(0, 40);
  }
  if (/\b(?:speak|answer|respond|write|teach|instruct|explain|translate| in | into )\b/i.test(question)) {
    for (const [pattern, name] of NAMED) {
      if (pattern.test(question)) return name;
    }
  }
  return chosen.trim() || "English";
}

export async function answerStory(title: string, summary: string, question: string, envKey: string, chosen = "English") {
  const key = envKey.trim();
  if (!key) throw new Error("Vibe is not connected on this desk yet.");
  const language = languageFor(question, chosen);

const res = await fetch("https://api.openai.com/v1/chat/completions", {
  method: "POST",
  headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
  signal: AbortSignal.timeout(25000),
  body: JSON.stringify({
    model: "gpt-4o-mini",
    temperature: 0.2,
    max_tokens: 420,
    messages: [
      {
        role: "system",
        content: `You are Vibe at VibeTok Clinic, reading one Desk Note story. Use only the headline and summary. Do not invent names, numbers, dates, places, or sources. If the story does not say it, say that in one sentence. No more than 120 words. Do not repeat the headline as the whole answer. If they ask you to teach or instruct, give that lesson in ${language}, still only from this story. Write the entire answer in ${language}. Do not add an English translation unless ${language} is English. Keep personal names, place names, and numbers as they appear in the story.`,
      },
      {
        role: "user",
        content: `Headline: ${title}\nSummary: ${summary || "The summary is the same as the headline."}\nQuestion: ${question}\nAnswer in: ${language}`,
      },
    ],
  }),
});
if (!res.ok) throw new Error("Vibe did not answer. Try again.");
const payload = (await res.json()) as { choices?: { message?: { content?: string } }[] };
const answer = payload.choices?.[0]?.message?.content?.trim();
if (!answer) throw new Error("Vibe did not answer. Try again.");
const thin = /does not say|not in the story|not in this story/i.test(answer);
const spoken = `${answer}\n\nConfidence: ${thin ? "Low" : "Moderate"}\nHallucination check: ${thin ? "the story does not support that." : "limited to the headline and summary on this desk."}\nSources: Desk Note story`;

  const { attachHard, hardRows } = await import("@/lib/vibe-hard");
  const asked = `${question}\n${title}\n${summary}`;
  return hardRows(asked).some((row) => row.quantity > 0) ? attachHard(asked, spoken) : spoken;
}

