  if (/\bpoll|survey|leads|ahead|deadlock|tied\b/i.test(title)) return "Written like a scoreboard. A lead here is not the election.";
  if (/\bcampaign|rally|candidate|debate|ballot\b/i.test(title)) return "Written as a stop on the trail. An appearance is not a result.";
  if (/\bcourt|judge|charged|lawsuit|ruling\b/i.test(title)) return "Written as one step in a case. A charge is not a finding.";
  if (/\bwar|attack|killed|troops|missile\b/i.test(title)) return "Written as an early account. Early accounts leave out who did what.";
  return "Written as a straight report. The headline names a subject and stops.";
}

