export type ScoreCard = {
  id: string;
  lane: string;
  title: string;
  outlet: string;
  href: string;
  published: string;
  truth: number;
};

const PLAIN_LABEL: Record<string, string> = {
  "Starts at 55": "Starting point",
  "Names a known source": "Names something you can look up",
  "Sweeping words": "Speaks in absolutes",
  "Soft words": "Sounds unsure on purpose",
  "Number with no source": "A figure with no counter",
};

function seedOf(title: string) {
  let n = 0;
  for (let i = 0; i < title.length; i++) n = (n * 33 + title.charCodeAt(i)) >>> 0;
  return n;
}

function pick(rows: string[], seed: number, salt: number) {
  return rows[(seed + salt) % rows.length];
}

function storyKind(title: string) {
  if (/\bfact-?check|misleading|false claim/i.test(title)) return "check";
  if (/\bpoll|survey|leads|ahead|trailing|deadlock|tied\b/i.test(title)) return "poll";
  if (/\bcourt|judge|sentenc|charged|lawsuit|ruling\b/i.test(title)) return "court";
  if (/\bstorm|heat wave|wildfire|hurricane|flood|earthquake\b/i.test(title)) return "weather";
  if (/\bstock|nasdaq|shares|layoff|economy|wall street\b/i.test(title)) return "market";
  if (/\bwar|airstrike|attack|killed|troops|missile\b/i.test(title)) return "conflict";

  if (/\bhospital|virus|vaccine|outbreak|cancer\b/i.test(title)) return "health";
  if (/\bcampaign|rally|candidate|debate|ballot|senate|governor|congress|midterm\b/i.test(title)) return "campaign";
  return "plain";
}

function explain(title: string, outlet: string, lane: string, parts: ScorePart[], truth: number) {
  const seed = seedOf(title);
  const kind = storyKind(title);
  const moved = parts.filter((part) => part.label !== "Starts at 55");
  const openers: Record<string, string[]> = {
    poll: [
      `${outlet} wrote this like a scoreboard. Someone is said to be ahead. A headline lead is one look at a race, not the election itself.`,
      `This is a horse-race line from ${outlet}. It tells you who the story says is in front. It does not tell you the votes have been cast.`,
      `${outlet} is framing a contest. The useful missing piece is who was asked, and when. Those details are not in the headline.`,
    ],
    campaign: [
      `${outlet} is covering a stop on the trail. The headline records that a candidate showed up. It does not measure whether anyone changed their mind.`,
      `Read this as campaign travel, not as a result. ${outlet} is following a person through an event. An appearance is not a lead in the polls.`,
      `${outlet} frames the day as politics in motion. You learn that something was held. You do not learn whether it mattered.`,
    ],
    court: [
      `${outlet} is reporting a step in a legal case. A charge, a sentence, or a ruling is one stage. It is not the whole question of what happened.`,
      `Treat this as a courthouse note from ${outlet}. The headline names a proceeding. The file, the evidence, and the other side are not in this one line.`,

    `${outlet} states this in a straight news voice. The headline names a subject and stops. It does not ask you to pick a side.`,
    `This is a plain report from ${outlet}. You get the topic. You do not get a verdict on who is right.`,
    `${outlet} wrote a label more than an argument. The words point at an event. They do not explain why it should change your mind.`,
  ],
};
const lines = [pick(openers[kind], seed, 1)];
if (!moved.length) {
  lines.push(
    pick(
      [
        `The words themselves are ordinary, so the number stays at ${truth}. Nothing in the line demanded extra trust, and nothing in it shouted a claim too big for a headline.`,
        `${truth} means the desk left this alone. No “always,” no “never,” and no law cited. Ordinary is not the same as unimportant.`,
        `Because the wording does not overreach, the score sits at ${truth}. That is a comment on the sentence, not a grade for the people in the story.`,
      ],
      seed,
      2,
    ),
  );
} else {
  for (const part of moved) {
    if (part.label === "Names a known source") {
      lines.push(
        pick(
          [
            `It names a source a reader can open, so the desk adds points. A named source is a trail. It is not proof the story got the source right.`,
            `The line points at a public document or a known authority. That is why the number rises. You can still disagree with how ${outlet} used it.`,
          ],
          seed,
          3,
        ),
      );
    }
    if (part.label === "Sweeping words") {
      lines.push(
        pick(
          [

            `It speaks in absolutes, the kind of words that cover everyone or never. Those are hard to defend from a headline, so the number comes down.`,
            `A word like “every,” “never,” or “completely” makes the claim larger than one story can carry. The desk marks that down.`,
          ],
          seed,
          4,
        ),
      );
    }
    if (part.label === "Soft words") {
      lines.push(
        pick(
          [
            `It hedges, with a word such as “may” or “could.” That is caution. The score dips a little because the headline is not actually sure.`,
            `${outlet} is not stating this as fact. The soft wording is honest, and the desk still notes that the claim is unfinished.`,
          ],
          seed,
          5,
        ),
      );
    }
    if (part.label === "Number with no source") {
      lines.push(
        pick(
          [
            `A number appears, and the headline does not say who counted it. Figures feel solid. Without a counter, they are just digits in a sentence.`,
            `The line leans on a figure. ${outlet} does not, in this headline, say where the figure came from, so the desk takes points off.`,
          ],
          seed,
          6,
        ),
      );
    }
  }
}
lines.push(
  pick(
    [
      truth >= 70
        ? `In short: the words are careful. ${truth} is not a finding that the story is true.`
        : truth >= 50
          ? `In short: ${truth} is a middle score. The headline is readable. It has not earned a gold star, and it has not been caught overreaching.`
          : `In short: ${truth} means the wording pushes harder than a headline can prove. Read the story before you repeat the claim.`,

        truth >= 70
          ? `Put simply, this line shows its work better than most headlines. ${truth} still is not a fact-check of the article.`
          : truth >= 50
            ? `Put simply, nothing in the sentence is wild. ${truth} will not tell you who should win, or who is lying.`
            : `Put simply, slow down on this one. ${truth} is the desk saying the words got ahead of the evidence in the headline.`,
      ],
      seed,
      8,
    ),
  );
  const compare = pick(
    [
      `The bars are other ${lane.toLowerCase()} headlines on the desk right now. A longer bar means calmer or better-sourced words. It does not mean that outlet is right, and it does not mean a candidate is ahead.`,
      `Use the bars only to compare wording inside ${lane.toLowerCase()}. Length is not popularity, and it is not a forecast.`,
      `Side by side, these are today’s ${lane.toLowerCase()} lines. The one you opened is marked. Taller is not “more true.”`,
    ],
    seed,
    9,
  );
  const evidence = pick(
    [
      `that page is the evidence. This desk read the headline. It did not call the people in the story.`,
      `open it before you repeat the claim. The card is a reading of the headline, not a report from the scene.`,
      `the article is the source. Nothing on this card replaces reading it.`,
    ],
    seed,
    10,
  );
  return { lines, compare, evidence };
}

function Bar({ label, points, scale, signed }: { label: string; points: number; scale: number; signed?: boolean }) {
