import { loadWeather, type Sky, type WeatherStory } from "@/lib/weather.functions";

const WET = /rain|storm|snow|shower|thunder|drizzle|sleet/i;

function weekLines(sky: Sky) {
  const highs = sky.days.map((day) => day.high).filter((n): n is number => n !== null);
  if (highs.length < 3) return ["Not enough days came back to describe the week."];
  const mid = Math.ceil(highs.length / 2);
  const avg = (rows: number[]) => rows.reduce((sum, n) => sum + n, 0) / rows.length;
  const swing = Math.round(avg(highs.slice(mid)) - avg(highs.slice(0, mid)));
  const warmest = sky.days.reduce((best, day) => ((day.high ?? -999) > (best.high ?? -999) ? day : best), sky.days[0]);
  const coolest = sky.days.reduce((best, day) => ((day.high ?? 999) < (best.high ?? 999) ? day : best), sky.days[0]);
  const wetDays = sky.days.filter((day) => WET.test(day.short));
  const trend =
    swing >= 4
      ? `The week warms. Later daytime highs average about ${swing} degrees above the earlier ones.`
      : swing <= -4
        ? `The week cools. Later daytime highs average about ${Math.abs(swing)} degrees below the earlier ones.`
        : "The week holds steady. Later daytime highs stay within a few degrees of the earlier ones.";
  const wet = wetDays.length
    ? `Wet days: ${wetDays.map((day) => day.name).join(", ")}. The forecast mentions rain, snow, or storms on those days.`
    : "No day in this stretch mentions rain, snow, or storms.";
  return [

    `Read the graph from left to right. The upper line is the daytime high. The lower line is the overnight low. Both come from the ${sky.unit === "C" ? "local forecast" : "National Weather Service forecast"} for ${sky.place}.`,
    `Highs run from ${Math.min(...highs)}° to ${Math.max(...highs)}°. ${warmest.name} is the warmest day${warmest.high !== null ? `, at ${warmest.high}°` : ""}. ${coolest.name} is the coolest daytime high${coolest.high !== null ? `, at ${coolest.high}°` : ""}.`,
    trend,
    wet,
    "This is only the coming week. It is not what October is like in a normal year.",
  ];
}

function boardRead(skies: Sky[]) {
  if (skies.length < 2) return "";
  const warm = skies.reduce((best, sky) => (sky.temp > best.temp ? sky : best), skies[0]);
  const cold = skies.reduce((best, sky) => (sky.temp < best.temp ? sky : best), skies[0]);
  const wet = skies.filter((sky) => WET.test(`${sky.short} ${sky.days.map((day) => day.short).join(" ")}`));
  return `Right now ${warm.place} is the warmest of these cities at ${warm.temp}°, and ${cold.place} is the coolest at ${cold.temp}°. ${wet.length ? `${wet.map((sky) => sky.place).join(", ")} ${wet.length === 1 ? "has" : "have"} rain, snow, or storms in the forecast.` : "None of these cities has rain, snow, or storms in the current period."}`;
}

function TempGraph({ sky }: { sky: Sky }) {
  const days = sky.days;
  const nums = days.flatMap((day) => [day.high, day.low].filter((n): n is number => n !== null));
  if (days.length < 2 || nums.length < 2) return null;
  const min = Math.min(...nums) - 3;
  const max = Math.max(...nums) + 3;
  const width = 640;
  const height = 180;
  const xAt = (index: number) => 36 + (index / (days.length - 1)) * (width - 72);

const yAt = (value: number) => 20 + ((max - value) / (max - min || 1)) * (height - 56);
const path = (pick: (day: (typeof days)[number]) => number | null) =>
  days
    .map((day, index) => {
      const value = pick(day);
      return value === null ? null : `${xAt(index)},${yAt(value)}`;
