function PictureRead({ item, onClose }: { item: SportsItem; onClose: () => void }) {
  const [wait, setWait] = useState(WAITING);
  const [answer, setAnswer] = useState("");
  const [lines, setLines] = useState<string[]>([]);
  const [note, setNote] = useState("");
