  useEffect(() => {
    let cancel = false;
    setWait(WAITING);
    setAnswer("");
    setLines([]);
    setNote("");
    setError("");
    void (async () => {
      try {
        const page = item.href ? await openPage({ data: { url: item.href, headline: item.title } }) : null;

      const parts = (page?.details ?? []).map((line) => line.trim()).filter(Boolean);
      if (cancel) return;
      setLines(parts);
      setNote(page?.note || "");
      const result = await askVibe({
        data: {
          title: item.title,
          summary: parts.join("\n\n") || item.title,
          language: "English",
          question: "Read this source and summarise it for someone who clicked the picture. Say what happened, the result, and what the page does not say. Stay on this event.",
        },
      });
      if (!cancel) setAnswer(result.answer);
    } catch (err) {
      if (!cancel) setError(err instanceof Error ? err.message : "Vibe could not read that source.");
    } finally {
      if (!cancel) setWait("");
    }
  })();
  return () => {
    cancel = true;
  };
}, [item]);

