};

type Splash = { id: number; x: number; y: number; dx: number };

function compact(count: number) {
  if (count < 1000) return String(count);
  const value = count / 1000;
  return `${value >= 10 ? Math.round(value) : value.toFixed(1).replace(/\.0$/, "")}K`;
}

function shortStory(title: string, summary: string) {
  const text = (summary && summary.trim() !== title.trim() ? summary : title).replace(/\s+/g, " ").trim();
  const sentences = text.match(/[^.!?]+[.!?]+|[^.!?]+$/g) ?? [text];
  const short = sentences.slice(0, 3).join(" ").trim();
  return /[.!?]$/.test(short) ? short : `${short}.`;
}

function stillMissing(title: string) {
  if (/\bpoll|survey|leads|ahead\b/i.test(title)) return "Still unstated: who was asked, how many, and when.";
  if (/\d/.test(title)) return "Still unstated: who counted the figure, and what was left out of it.";
  if (/\bcourt|judge|charged|lawsuit|ruling\b/i.test(title)) return "Still unstated: whether this is a charge, a filing, or a finding.";
  return "Still unstated: the document, the other side, and what happened next.";
}

function focusNote() {
  const box = document.getElementById("story-note") ?? document.getElementById("story-note-gate");

  box?.scrollIntoView({ behavior: "smooth", block: "center" });
  if (box instanceof HTMLTextAreaElement) box.focus();
}

function downloadCard(file: File) {
  const url = URL.createObjectURL(file);
  const link = document.createElement("a");
  link.href = url;
  link.download = file.name;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 4000);
}

export function StoryBar({
  title,
  summary,
  href,
  openVibe,
  onComment: openComment,
