  title: string;
  summary: string;
  href?: string;
  openVibe?: boolean;
  onComment?: () => void;
}) {
  const [marks, setMarks] = useState<Marks>({ like: 0, repost: 0, study: 0, mine: { like: false, repost: false, study: false } });
  const [comments, setComments] = useState(0);
  const [note, setNote] = useState("");
  const [panel, setPanel] = useState<"" | "study" | "meaning" | "send" | "vibe">("");
  const [hearts, setHearts] = useState<Splash[]>([]);
  const [busy, setBusy] = useState("");

  useEffect(() => {
    if (openVibe) setPanel("vibe");
  }, [openVibe]);

  useEffect(() => {
    let cancel = false;
    void listMarks({ data: { title } })
      .then((rows) => {
        if (!cancel) setMarks(rows);
      })
      .catch(() => undefined);
    void listNotes({ data: { title } })
      .then((rows) => {
        if (!cancel) setComments(rows.length);
      })
      .catch(() => undefined);
    return () => {
      cancel = true;
    };
  }, [title]);

  async function onMark(kind: "like" | "repost" | "study") {
    setBusy(kind);
    try {
      setMarks(await toggleMark({ data: { title, kind } }));
      if (kind !== "like") setNote(kind === "repost" ? "Copied, and the repost is saved." : "Saved with this story.");
    } catch {

    if (kind !== "like") setNote("Sign in on this story to save a repost or a study.");
  } finally {
    setBusy("");
  }
}

function onLike(event: React.MouseEvent<HTMLButtonElement>) {
  const rect = event.currentTarget.getBoundingClientRect();
  const x = rect.left + rect.width / 2;
  const y = rect.top + rect.height / 2;
  const burst = [-34, -12, 12, 36].map((dx, index) => ({ id: Date.now() + index, x, y, dx }));
  setHearts(burst);
  window.setTimeout(() => setHearts([]), 900);
  void onMark("like");
}

function onComment() {
  setPanel("");
  if (openComment) {
    sessionStorage.setItem("desk-note-for", title);
    openComment();
    return;
  }
  focusNote();
  setNote("The note box is open.");
}

function onStudy() {
  setPanel((open) => (open === "study" ? "" : "study"));
  setNote("");
  void onMark("study");
}

async function onShare(name: string, hrefTo: string) {
  const text = storyCaption(title, summary);
  try {
    const file = await storyCardFile(title, summary);
    if (typeof navigator.share === "function") {
      const data: ShareData = { files: [file], title: "VibeTok Clinic", text };
      try {
        if (typeof navigator.canShare !== "function" || navigator.canShare({ files: [file] })) {
          await navigator.share(data);
          setNote("Share menu is open. Send the card. The headline is once, and the VibeTok logo is on it.");
          return;
        }
      } catch (err) {
        if ((err as Error).name === "AbortError") return;
      }
    }
    downloadCard(file);
    if (name === "Instagram") window.open("https://www.instagram.com/", "_blank", "noopener,noreferrer");

    else if (hrefTo) window.open(hrefTo, "_blank", "noopener,noreferrer");
    setNote("The formatted card downloaded. Attach that picture so the VibeTok logo stays on the story.");
  } catch {
    setNote("The card could not be formatted.");
  }
}

