}

export function StorySummary({
  url,
  headline,
  outlet,
  onClose,
}: {
  url: string;
  headline: string;
  outlet: string;
  onClose: () => void;
}) {
  const [title, setTitle] = useState("");
  const [summary, setSummary] = useState("");
  const [details, setDetails] = useState<string[]>([]);
  const [blocked, setBlocked] = useState(false);
  const [stoodIn, setStoodIn] = useState("");
  const [blockedOutlet, setBlockedOutlet] = useState("");
  const [also, setAlso] = useState<string[]>([]);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(true);

  useEffect(() => {
    let cancel = false;
    setBusy(true);
    setError("");
    setBlocked(false);
    setStoodIn("");
    setAlso([]);
    void summarizeStory({ data: { url, headline, outlet } })
      .then((page) => {
        if (cancel) return;
        setTitle(page.title);
        setSummary(page.summary);
        setDetails(page.details.length ? page.details : [page.summary]);
        setBlocked(page.blocked);
        setStoodIn(page.stoodIn);
        setBlockedOutlet(page.blockedOutlet);
        setAlso(page.also.map((item) => item.outlet));
      })
      .catch((err: unknown) => {

      if (!cancel) setError(err instanceof Error ? err.message : "Could not summarize that page.");
    })
    .finally(() => {
      if (!cancel) setBusy(false);
    });
  return () => {
    cancel = true;
  };
}, [url, headline, outlet]);

return (
  <div className="fixed inset-0 z-50 grid place-items-start overflow-y-auto bg-bg/80 px-4 py-8" role="presentation" onClick={onClose}>
