function when(at: string) {
  const time = Date.parse(at);
  if (Number.isNaN(time)) return "";
  return new Date(time).toLocaleString([], { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });
}

function showText(value: string) {
  return value
    .replace(/&#x([0-9a-f]+);/gi, (_, hex: string) => String.fromCharCode(Number.parseInt(hex, 16)))
    .replace(/&#(\d+);/g, (_, n: string) => String.fromCharCode(Number(n)))
    .replace(/'/gi, "'")
    .replace(/"/gi, '"')
    .replace(/&/gi, "&");
}

export function StoryThread({
  title,
  url,
  outlet,
  notesOnly,
}: {
  title: string;
  url?: string;
  outlet?: string;
  notesOnly?: boolean;
}) {
  const [notes, setNotes] = useState<Note[]>([]);
  const [body, setBody] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [reading, setReading] = useState(false);
  const [summary, setSummary] = useState("");
  const [details, setDetails] = useState<string[]>([]);
  const [summaryTitle, setSummaryTitle] = useState("");
  const [blocked, setBlocked] = useState(false);
  const [stoodIn, setStoodIn] = useState("");
  const [blockedOutlet, setBlockedOutlet] = useState("");
  const [also, setAlso] = useState<string[]>([]);

  useEffect(() => {
    if (sessionStorage.getItem("desk-note-for") !== title) return;
    sessionStorage.removeItem("desk-note-for");

  const timer = window.setTimeout(() => {
