async function onCheckLinks() {
  const hrefs = [
    ...read.sentences.flatMap((s) => (s.citation ? [s.citation.href] : [])),
    ...read.sentences.flatMap((s) => s.caseLaw.map((c) => c.href)),
  ];
  const unique = [...new Set(hrefs)].slice(0, 8);
  if (!unique.length) {
    setNotice("Nothing in this hearing names a link this desk can check.");
    return;
  }
  setBusy("links");
  setError("");
  try {
    const result = await checkLinks({ data: { hrefs: unique } });
    setLinks((prev) => {
      const next = { ...prev };
      for (const row of result.results) next[row.href] = { ok: row.ok, status: row.status };
      return next;
    });
    const answered = result.results.filter((row) => row.ok).length;
    setJob({ at: stamp(), line: `${answered} of ${result.results.length} links answered.` });

  } catch (err) {
    setError(err instanceof Error ? err.message : "Link check failed.");
  } finally {
    setBusy(null);
  }
}

